COLLDATA("seeratency","ur",[[2171,"’’اور زمین پر چلنے والے ہر جاندار کا رزق اللہ کے ذمے ہے۔‘‘(1)\n﴿إِنَّ اللهَ هُوَ الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ﴾\n’’بلاشبہ اللہ ہی رزق دینے والا، بڑی قوت والا، نہایت طاقت ور ہے۔‘‘(2)\n§رزق کی فراخی اور تنگی اللہ کی منشا پر موقوف ہے\nمدینہ کی اسلامی ریاست میں حق معیشت میں تمام شہری مساوی قرار پائے لیکن درجات معیشت میں مساوات نہیں ہے۔ معیشت میں درجات کا تفاوت ایک حد تک فطری ہے، یعنی ضروری نہیں کہ ہر ایک کے پاس ایک ہی طرح کا سامان معیشت ہو۔ قرآن مجید نے اس تفاوت درجات کو اس طرح بیان کیا ہے:\n﴿نَحْنُ قَسَمْنَا بَيْنَهُمْ مَعِيشَتَهُمْ فِي الْحَيَاةِ الدُّنْيَا وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضٍ دَرَجَاتٍ﴾\n’’ہم نے دنیاوی زندگی میں ان کے درمیان ان کی روزی تقسیم کر دی ہے اور ہم ہی نے درجات میں انھیں ایک دوسرے پر برتری دی ہے۔‘‘(3)\n﴿اللهُ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ وَيَقْدِرُ﴾\n’’اللہ جسے چاہے کھلا رزق دیتا ہے اور (جسے چاہے اس کا رزق) تنگ کر دیتا ہے۔‘‘(4)\nچونکہ رزق کا ذمہ دار اور معیشت کا کارساز خود اللہ تعالیٰ ہے، لہذا جو لوگ تنگ دستی کے ڈر سے اپنی اولاد کو قتل کر دیتے تھے، انھیں اس قبیح فعل سے روک دیا گیا۔ فرمایا:\n﴿وَلَا تَقْتُلُوا أَوْلَادَكُمْ مِنْ إِمْلَاقٍ نَحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ﴾\n’’اور اپنی اولاد کو تنگ دستی کے ڈر سے قتل نہ کرو، تمھیں بھی اور انھیں بھی ہم ہی رزق دیتے ہیں۔‘‘(5)\nان آیات میں بلا امتیاز ہر فرد کو بتا دیا گیا ہے کہ تمھاری معاش اور اسباب معیشت اللہ تبارک و تعالیٰ ہی کے خزانوں ہی سے دیے جاتے ہیں۔ وہ جسے جتنا چاہے عطا کر دے۔ ہر شخص کو حق حاصل ہے کہ محنت کرے اور اللہ کے فضل و کرم سے فائدہ اٹھائے۔\n§رزق حلال کمانا اہم فرض ہے\nنبی صلی اللہ علیہ وسلم نے حلال رزق کمانے کے فضائل بیان فرمائے تاکہ ہر مسلمان جدوجہد کر کے اسلامی ریاست کا ایک","",{"v":500101,"fn":"(1) ہود 11:6 ،\n(2) الذریت 51:58 ،\n(3) الزخرف 43:32 ،\n(4) الرعد 13:26 ،\n(5) الانعام 6:151"}],[2172,"سرگرم، فعال اور مفید شہری بن جائے اور دین حنیف کی تبلیغ، ریاست کی ترقی اور غریبوں اور ناداروں کی بھلائی میں اپنا کردار ادا کرے۔ فرمان نبوی ہے:\n﴿طَلَبُ كَسْبِ الْحَلَالِ فَرِيضَةٌ بَعْدَ الْفَرِيضَةِ﴾\n’’حلال معیشت کا طلب کرنا اللہ تعالیٰ کی عبادت کے فریضے کے بعد سب سے بڑا فریضہ ہے۔‘‘(1)\nمومنوں کو ترغیب دلائی گئی کہ وہ ادائے نماز کے بعد میدان عمل میں نکلیں اور محنت کریں۔ اللہ تعالیٰ کا ارشاد عالی ہے:\n﴿فَإِذَا قُضِيَتِ الصَّلَاةُ فَانْتَشِرُوا فِي الْأَرْضِ وَابْتَغُوا مِنْ فَضْلِ اللهِ﴾\n’’پھر جب نماز پوری ہو جائے تو تم زمین میں پھیل جاؤ اور اللہ کا فضل تلاش کرو۔‘‘(2)\nایک اور آیت میں تلاش رزق کی ترغیب یوں دی گئی:\n﴿إِنَّ الَّذِينَ تَعْبُدُونَ مِنْ دُونِ اللهِ لَا يَمْلِكُونَ لَكُمْ رِزْقًا فَابْتَغُوا عِنْدَ اللهِ الرِّزْقَ﴾\n’’بلاشبہ اللہ کے سوا جن کی تم عبادت کرتے ہو، وہ تمھارے لیے رزق کا اختیار نہیں رکھتے، لہذا تم اللہ ہی کے ہاں رزق تلاش کرو۔‘‘(3)\n﴿وَآخَرُونَ يَضْرِبُونَ فِي الْأَرْضِ يَبْتَغُونَ مِنْ فَضْلِ اللهِ﴾\n’’اور کتنے اور (مومن) زمین میں اللہ کا فضل (رزق) ڈھونڈتے پھریں گے۔‘‘(4)\n§سود کا خاتمہ …… عادلانہ معیشت کی اساس\nاسلام نے حصول دولت کے تمام حرام راستے مسدود کر دیے اور حلال ذرائع سے آگے بڑھنے کے مواقع فراہم کیے، نیز کسب معاش اور مصرف مال کے سلسلے میں ایک بنیادی اصول طے کر دیا۔ فرمان نبوی ہے:\n﴿لَا تَزُولُ قَدَمَا ابْنِ آدَمَ يَوْمَ الْقِيَامَةِ مِنْ عِنْدِ رَبِّهِ حَتَّى يُسْأَلَ عَنْ خَمْسٍ﴾\n’’ابن آدم کے قدم قیامت کے روز اپنے پروردگار کے پاس سے اٹھ نہیں سکیں گے جب تک کہ اس سے پانچ سوال نہ کر لیے جائیں۔‘‘\nان پانچ سوالوں میں دو سوال یہ ہیں:\n﴿وَعَنْ مَالِهِ مِنْ أَيْنَ اكْتَسَبَهُ وَفِيمَا أَنْفَقَهُ﴾","",{"v":500102,"fn":"(1) السنن الکبریٰ للبیہقی: 128/6 ،\n(2) الجمعۃ 62:10 ،\n(3) العنکبوت 29:17 ،\n(4) المزمل 73:20"}],[2173,"’’اور اس کے مال کے بارے میں (پوچھا جائے گا) کہ وہ کہاں سے کمایا اور کہاں خرچ کیا۔‘‘(1)\nنبی صلی اللہ علیہ وسلم کا مطمح نظر ایک ایسے معاشرے کا قیام تھا جس میں اچھائیاں فروغ پائیں اور برائیوں کا خاتمہ ہو۔ لوگوں کے حقوق محفوظ ہوں، معاشی ظلم و نا انصافی کا خاتمہ ہو۔ اخلاقی فضائل نشو و نما پائیں اور پھلیں پھولیں۔ رسول اللہ صلی اللہ علیہ وسلم کی بھرپور کوشش یہی تھی کہ معاشی انصاف کا نظام رضا کارانہ طور پر بغیر کسی جبر کے قائم کیا جائے۔ لوگوں کی معاشی سرگرمیاں حلال اور جائز طریقے سے فروغ پائیں اور معاش و اقتصاد کے معاملات میں کسی طرح کے ظلم، دھوکے اور فریب کا شائبہ تک نہ ہو، چنانچہ اس دور میں سود خوری جیسے ظالمانہ کاروبار کو جڑ سے اکھاڑ پھینکا گیا۔ اللہ تبارک و تعالیٰ نے قرآن کریم میں مختلف مقامات پر تجارت کی حلت اور سود کی حرمت کا اعلان فرمایا ہے۔ اسلام نے نہ صرف سود کی حرمت کو عام کر دیا بلکہ پچھلے سارے سودی معاہدے بھی منسوخ کر دیے۔ قرآن مجید اس بارے میں خبردار کرتا ہے:\n﴿الَّذِينَ يَأْكُلُونَ الرِّبَا لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ مِنَ الْمَسِّ ذَلِكَ بِأَنَّهُمْ قَالُوا إِنَّمَا الْبَيْعُ مِثْلُ الرِّبَا وَأَحَلَّ اللهُ الْبَيْعَ وَحَرَّمَ الرِّبَا فَمَنْ جَاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانْتَهَى فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللهِ وَمَنْ عَادَ فَأُولَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ ۝ يَمْحَقُ اللهُ الرِّبَا وَيُرْبِي الصَّدَقَاتِ وَاللهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ ۝ إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَأَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ ۝ يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنْتُمْ مُؤْمِنِينَ﴾\n’’جو لوگ سود کھاتے ہیں، وہ (قیامت کے دن) اس شخص کی طرح کھڑے ہوں گے جسے شیطان نے چھو کر بدحواس کر دیا ہو۔ یہ (سزا) اس لیے ملے گی کہ وہ کہتے تھے: تجارت بھی سود ہی کی طرح ہے، حالانکہ اللہ نے تجارت کو حلال کیا ہے اور سود کو حرام، پھر جس شخص کے پاس اس کے رب کی طرف سے نصیحت آ جائے اور وہ (سود کھانے سے) باز رہے تو جو کچھ وہ پہلے کھا چکا سو کھا چکا، اس کا معاملہ اللہ کے حوالے ہے اور جو شخص دوبارہ (سودی معاملہ) کرے تو ایسے لوگ دوزخی ہیں، وہ اس میں ہمیشہ رہیں گے۔ اللہ سود کو مٹاتا ہے اور صدقات کو بڑھاتا ہے اور اللہ کسی ناشکرے گناہ گار کو پسند نہیں کرتا۔ بے شک جو لوگ ایمان لائے اور انھوں نے نیک عمل کیے اور نماز قائم کی اور وہ زکاۃ ادا کرتے رہے، ان کے لیے ان کے رب کے پاس","",{"v":500103,"fn":"(1) جامع الترمذی: 2416"}],[2174,"اجر ہے، نہ ان پر کوئی خوف ہوگا اور نہ وہ غمگین ہوں گے۔ اے لوگو جو ایمان لائے ہو! اللہ سے ڈرو اور جو سود باقی ہے وہ چھوڑ دو اگر تم مومن ہو۔(1)\n§ارتکاز دولت کی ممانعت\nسونا چاندی جمع کر لینے اور اللہ کی راہ میں خرچ نہ کرنے پر قرآن مجید نے سخت وعید سنائی ہے اور ذخیرہ اندوزی اور مال جوڑ جوڑ کر رکھنے کو حرام قرار دیا ہے تا کہ دولت سمٹ کر خاص حلقوں اور محدود طبقات میں محصور نہ ہو جائے۔ فرمان الہی ہے:\n﴿وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلَا يُنْفِقُونَهَا فِي سَبِيلِ اللهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ ۝ يَوْمَ يُحْمَى عَلَيْهَا فِي نَارِ جَهَنَّمَ فَتُكْوَى بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ هَذَا مَا كَنَزْتُمْ لِأَنْفُسِكُمْ فَذُوقُوا مَا كُنْتُمْ تَكْنِزُونَ ۝﴾\n’’اور جو لوگ سونا اور چاندی جمع کرتے ہیں اور اسے اللہ کی راہ میں خرچ نہیں کرتے، آپ انھیں درد ناک عذاب کی خبر سنا دیں۔ جس دن وہ مال دوزخ کی آگ میں تپایا جائے گا، پھر اس سے ان کے ماتھوں، ان کے پہلوؤں اور ان کی پیٹھوں کو داغا جائے گا (اور کہا جائے گا:) یہ ہے وہ (مال) جو تم نے اپنے لیے جمع کر کے رکھا تھا، لہذا (اب اس کا مزہ) چکھو جو تم جمع کرتے رہے۔‘‘(2)\n§دھوکے دھڑی سے ایک دوسرے کا مال کھانا حرام ہے\nاللہ تبارک و تعالیٰ نے ظلم و جور سے ایک دوسرے کا مال کھانا حرام ٹھہرایا ہے۔ باری تعالیٰ کا فرمان ہے:\n﴿يَاأَيُّهَا الَّذِينَ آمَنُوا لَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ إِلَّا أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ﴾\n’’اے لوگو جو ایمان لائے ہو! تم آپس میں ایک دوسرے کے مال ناحق نہ کھاؤ، مگر یہ کہ آپس کی رضا مندی سے تجارت ہو۔‘‘(3)\nناپ تول میں کمی کو نہایت مہلک فعل بتلایا گیا ہے، فرمان الہی ہے:\n﴿وَيْلٌ لِلْمُطَفِّفِينَ ۝ الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ ۝ وَإِذَا كَالُوهُمْ أَوْ وَزَنُوهُمْ يُخْسِرُونَ ۝﴾\n’’ڈنڈی مارنے والوں کے لیے تباہی ہے۔ جب وہ لوگوں سے ناپ کر لیں تو پورا لیتے ہیں۔ اور جب وہ","",{"v":500104,"fn":"(1) البقرۃ 2:275-278\n(2) التوبۃ 9:34,35\n(3) النساء 4:29"}],[2175,"خود انھیں ناپ کر یا تول کر دیں تو کم دیتے ہیں۔‘‘(1)\nنیز حکم فرمایا:\n﴿وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ﴾\n’’اور سیدھی ترازو سے تولو۔‘‘(2)\n§شراب نوشی، جوا اور فال نکالنا شیطانی کرتوت ہیں\nنبی صلی اللہ علیہ وسلم نے ہر حرام چیز کی خرید و فروخت پر پابندی لگا دی تا کہ عوام کو حرام چیزوں سے نفرت ہو جائے اور حلال اور جائز سامان کی فراوانی ہو۔ اسلام میں شراب خوری اور قمار بازی وغیرہ کو شیطانی افعال قرار دیا گیا ہے۔ اس سلسلے میں قرآن مجید کا حکم ہے:\n﴿إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ وَالْأَزْلَامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ﴾\n’’بے شک شراب اور جوا اور آستانے اور فال نکالنے کے تیر سب گندے کام ہیں اور شیطان کے عمل سے ہیں، لہذا تم ان سے بچو۔‘‘(3)\n§گردش دولت کے عادلانہ اقدامات\nرسول اللہ صلی اللہ علیہ وسلم نے اسلام کے مالی نظام کی صراحت کرتے ہوئے ایسے احکام بھی بیان فرمائے جن کے ذریعے دولت گردش میں رہتی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص کسی زمین کو آباد کرے اور وہ زمین کسی اور کی ملکیت نہ ہو تو اسے آباد کرنے والا ہی اس کا زیادہ حق دار ہے۔‘‘ اس کے علاوہ اللہ تبارک و تعالیٰ نے قانون وراثت نازل فرمایا۔ آپ صلی اللہ علیہ وسلم نے گداگری کی شدید مذمت فرمائی اور خود اپنی محنت و مشقت سے حلال روزی کمانے کی ترغیب دی۔\nقدرتی وسائل اور بے کار اراضی کو زیر استعمال لانے کے لیے آپ کے اقدامات زمانے اور زندگی کے ہر موڑ پر چراغ راہ کا کام دیں گے۔ آپ صلی اللہ علیہ وسلم نے مختلف اشخاص کو جاگیریں عطا فرمائیں تا کہ معاشی حالت میں استحکام پیدا ہو اور یہ استحکام فلاح عامہ کا ذریعہ بنے۔","",{"v":500105,"fn":"(1) المطففین 83:1-3\n(2) بنی اسرائیل 17:35\n(3) المائدۃ 5:90"}],[2176,"§نظام زکاۃ، سرمایہ داری پر کاری ضرب\nدولت کی تقسیم اور سرمایہ و محنت کی جنگ بہت پرانی ہے۔ صنعتکار، جاگیردار اور سرمایہ دار آج تک اس مسئلے کا حل نہیں ڈھونڈ سکے۔ رسول اللہ صلی اللہ علیہ وسلم نے انفرادی و اجتماعی بہبود کے نقطہ نظر سے اس مسئلے کو زبردست اہمیت دی۔ دولت کی تقسیم کے لیے قرآنی احکام کے مطابق تقسیم ترکہ کا قانون نافذ کیا۔ ایسی وصیت پر پابندی لگا دی کہ کوئی شخص اپنی ساری دولت کسی ایک شخص کے نام کر دے۔ صرف ایک تہائی حصے کی وصیت کی اجازت دی۔ سودی لین دین کا مکمل خاتمہ کر دیا۔ جمع شدہ دولت اور جائیداد پر ادائے زکاۃ کو اسلام کے بنیادی رکن کی حیثیت سے لاگو کیا۔ آپ صلی اللہ علیہ وسلم نے سرمایہ داروں کے لیے لازم ٹھہرایا کہ وہ مزدوروں کی مزدوری ان کا پسینہ خشک ہونے سے پہلے ادا کر دیں اور مزدوروں کو تلقین فرمائی کہ وہ اپنے مالکان کے سونپے ہوئے فرائض پورے خلوص، خیر خواہی اور دیانتداری سے ادا کریں۔\nفی الجملہ آپ صلی اللہ علیہ وسلم نے گردش دولت کا نظام نافذ کر کے اسلامی ریاست کو بہت بڑے فتور و فساد سے محفوظ کر دیا۔ آج سرمایہ و محنت کے مسائل حل کرنے کا مدعی اشتراکی نظام خود اپنے وطن ہی میں نابود ہو چکا ہے اور بڑے بڑے ماہرین معاشیات اسلام کے اسی اقتصادی نظام کی افادیت کے معترف ہیں جو ریاست مدینہ میں نافذ کیا گیا۔\n§اسلامی ریاست کے وسائل\nاسلامی شریعت کی رو سے معاش و اقتصاد اور محصولات کے معاملات کو بڑی اہمیت حاصل ہے۔ دنیا کی کوئی حکومت مضبوط مالی وسائل کے بغیر نظم حکومت نہیں چلا سکتی۔ اسلام نے حکومت اور سیاسی و فلاحی نظم و نسق کے لیے جن مالی وسائل کو بروئے کار لانے کا نظام مرتب کیا ہے وہ بڑے معتدل، متوازن اور مبنی بر انصاف ہیں۔ ان کی رو سے ایک اسلامی مملکت کے وسائل آمدن یہ ہیں:\nپیداوار کا عشر، زکاۃ اور جزیہ وغیرہ۔ ان کے بغیر کوئی اسلامی حکومت مملکت کا انتظام نہیں چلا سکتی۔ رسول اللہ صلی اللہ علیہ وسلم نے ریاست مدینہ کے نظام مالیات کے استحکام پر بہت توجہ دی۔ ایسے قابل لوگوں کو مالیاتی ذمہ داریاں سونپیں جو دیانت داری، فرض شناسی اور فنی لحاظ سے سب سے زیادہ اہل تھے اور حساب کتاب میں مہارت تامہ رکھتے تھے۔ ریاست نبوی ایک فلاحی ریاست تھی۔ حلال روزی، عوام کی معاشی کفالت، قیام انصاف، ادائے حقوق اور غربت و افلاس اور معاشی ناہمواریاں ختم کرنا اس ریاست کے ترجیحی اہداف تھے۔ قرآن مجید نے معاشی ناہمواری اور ذرائع پیداوار پر چند لوگوں کی اجارہ داری کے خاتمے کے لیے عشر، زکاۃ کے جو احکام دیے ان کی غایت یہ بیان فرمائی:","",{"v":500106}],[2177,"﴿كَيْ لَا يَكُونَ دُولَةً بَيْنَ الْأَغْنِيَاءِ مِنْكُمْ﴾\n’’تا کہ وہ (مال) تمھارے دولت مندوں ہی کے درمیان گردش نہ کرتا رہے۔‘‘(1)\n§محصولات کے لیے بیت المال کا قیام\nاسلامی ریاست کی بنیادی پالیسی یہ تھی کہ لوگوں پر محصولات تو کم سے کم عائد کیے جائیں لیکن فائدے زیادہ سے زیادہ بہم پہنچائے جائیں۔ شہریوں کی بنیادی ضروریات کا بندوبست اور نادار لوگوں کی مدد اسلامی ریاست کا اہم ترین فریضہ تھا۔ اس کے لیے رسول اللہ صلی اللہ علیہ وسلم نے مرکزی بیت المال قائم کیا جس میں درج ذیل محاصل جمع ہوتے تھے: زکاۃ، صدقات و خیرات، مال غنیمت، عشور، مال فے، خراج، جزیہ۔ اللہ تبارک و تعالیٰ نے مال غنیمت سے خمس رسول اللہ صلی اللہ علیہ وسلم کے لیے خاص کر دیا تھا۔ مگر آپ صلی اللہ علیہ وسلم اپنی ضروریات کے بعد خمس کا مال بھی اسلامی ریاست کی فلاح و بہبود پر خرچ کرتے تھے۔\n[تصویر: احتجاجی کتبے پر لکھا جملہ: LET'S Bank THE muslim WAY?]\n15/10/2011 کو یورپ میں احتجاج (Occupy Street) میں احتجاجی کتبے پر لکھے جملے کا مطلب ہے: ’’آئیے اسلامی طریقے سے بینک چلائیں۔‘‘\n1 زکاۃ اسلام کا بنیادی رکن ہے\nاسلامی ریاست کے محاصل میں سب سے زیادہ اہمیت زکاۃ کی ہے۔ قرآن مجید نے ادائے نماز کے ساتھ ہی ادائے زکاۃ کا بھی حکم دیا ہے:\n﴿وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ﴾\n’’اور نماز قائم کرو اور زکاۃ دو اور رکوع کرنے والوں کے ساتھ رکوع کرو۔‘‘(2)\nنبی صلی اللہ علیہ وسلم نے ادائے زکاۃ کو اسلام کے پانچ بنیادی ارکان میں شامل فرمایا:\n﴿بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ﴾","",{"v":500107,"fn":"(1) الحشر 59:7\n(2) البقرۃ 2:43","im":["v5_p107.jpg"]}],[2178,"’’اسلام کی بنیاد پانچ چیزوں پر ہے: اس بات کی گواہی دینا کہ اللہ کے سوا کوئی معبود برحق نہیں اور یہ کہ محمد (صلی اللہ علیہ وسلم) اللہ کے رسول ہیں اور نماز قائم کرنا، زکاۃ ادا کرنا، حج کرنا اور رمضان کے روزے رکھنا۔‘‘(1)\nنبی صلی اللہ علیہ وسلم ریاست مدینہ کے سربراہ تھے، اللہ تبارک و تعالیٰ نے آپ کو بلحاظ منصب حکم دیا کہ ان کے اموال سے زکاۃ وصول کریں اور ان کے لیے دعا بھی فرمائیں۔ ارشاد ربانی ہے:\n﴿خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِمْ بِهَا وَصَلِّ عَلَيْهِمْ إِنَّ صَلَاتَكَ سَكَنٌ لَهُمْ وَاللهُ سَمِيعٌ عَلِيمٌ﴾\n’’(اے نبی!) ان کے مالوں میں سے صدقہ (زکاۃ) لیجیے (تا کہ) آپ اس کے ذریعے سے انھیں پاک کریں اور ان کا تزکیہ کریں اور ان کے لیے دعا کریں۔ بے شک آپ کی دعا ان کے لیے سکون (کا باعث) ہے اور اللہ خوب سننے والا (اور) خوب جاننے والا ہے۔‘‘(2)\nرسول اللہ صلی اللہ علیہ وسلم جب کسی صحابی کو کسی علاقے کا امیر مقرر فرما کر روانہ فرماتے تو اسے امر بالمعروف اور نہی عن المنکر کے ساتھ وصولی زکاۃ کا حکم دیتے تھے۔ ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا معاذ رضی اللہ عنہ کو یمن کی طرف بھیجتے وقت فرمایا:\n﴿فَأَعْلِمُهُمْ أَنَّ اللهَ افْتَرَضَ عَلَيْهِمْ صَدَقَةً فِي أَمْوَالِهِمْ تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ وَتُرَدُّ عَلَى فُقَرَائِهِمْ﴾\n’’انھیں بتانا کہ بلاشبہ اللہ نے ان پر ان کے اموال میں صدقہ (زکاۃ وغیرہ) فرض کیا ہے جو ان کے مالداروں سے لے کر ان کے محتاجوں کو دیا جائے گا۔‘‘(3)\nزمین کی پیداوار پر زکاۃ ادا کرنے کا حکم اس آیت میں دیا:\n﴿يَاأَيُّهَا الَّذِينَ آمَنُوا أَنْفِقُوا مِنْ طَيِّبَاتِ مَا كَسَبْتُمْ وَمِمَّا أَخْرَجْنَا لَكُمْ مِنَ الْأَرْضِ﴾\n’’اے لوگو جو ایمان لائے ہو! تم ان پاکیزہ چیزوں میں سے خرچ کرو جو تم کماتے ہو اور ان میں سے بھی جو ہم نے تمھارے لیے زمین میں سے نکالی ہیں۔‘‘(4)\n﴿كُلُوا مِنْ ثَمَرِهِ إِذَا أَثْمَرَ وَآتُوا حَقَّهُ يَوْمَ حَصَادِهِ﴾\n’’ان کا پھل کھاؤ جب وہ پھل لائیں اور ان کی کٹائی اور چنائی کے دن اس (اللہ) کا حق دے دیا کرو۔‘‘(5)","",{"v":500108,"fn":"(1) صحیح البخاری: 8\n(2) التوبۃ 9:103\n(3) صحیح البخاری: 1395، صحیح مسلم: 19\n(4) البقرۃ 2:267\n(5) الانعام 6:141"}],[2179,"سونے چاندی کی زکاۃ ادا کرنے کا حکم درج ذیل آیت مبارکہ سے عیاں ہے:\n﴿وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلَا يُنْفِقُونَهَا فِي سَبِيلِ اللهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ﴾\n’’اور جو لوگ سونا اور چاندی جمع کرتے ہیں اور اسے اللہ کی راہ میں خرچ نہیں کرتے، آپ انھیں درد ناک عذاب کی خبر سنا دیں۔‘‘(1)\n§ضرورت مندوں میں زکاۃ تقسیم کرنے کا حکم\nزکاۃ بیت المال میں جمع ہوتی ہے اور ریاست کے ضرورت مندوں میں تقسیم کی جاتی ہے، رسول اللہ صلی اللہ علیہ وسلم نے زکاۃ کی تقسیم کا طریق کار یہ بیان فرمایا ہے:\n﴿تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ وَتُرَدُّ عَلَى فُقَرَائِهِمْ﴾\n’’زکاۃ مالداروں سے لی جائے اور ان کے ناداروں میں تقسیم کی جائے۔‘‘(2)\nقرآن کریم نے زکاۃ کو فرض قرار دیا تو اس کے مصارف کا بھی تعین کر دیا:\n﴿إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللهِ وَابْنِ السَّبِيلِ فَرِيضَةً مِنَ اللهِ وَاللهُ عَلِيمٌ حَكِيمٌ﴾\n’’زکاۃ تو صرف فقیروں اور مسکینوں اور ان اہلکاروں کے لیے ہے جو اس (کی وصولی) پر مقرر ہیں اور ان کے لیے جن کی دلداری مقصود ہے اور گردنیں چھڑانے اور قرضہ داروں (کے قرض اتارنے) کے لیے اور اللہ کی راہ میں اور مسافروں (کی مدد) میں۔ (یہ) اللہ کی طرف سے فرض ہے اور اللہ خوب جاننے والا (اور) حکمت والا ہے۔‘‘(3)\n§زکاۃ ادا کرنے کی برکتیں\nبحیثیت مسلمان ہم صرف احکام الہی کے پابند ہیں۔ اللہ تعالیٰ کے احکام میں ہمارے لیے کون کون سے حکمتیں، برکتیں اور فائدے ہیں؟ یہ باتیں اللہ تعالیٰ اپنے رسول صلی اللہ علیہ وسلم کی معرفت خود بتا دے تو اس کا لطف و کرم ہے۔ اللہ تعالیٰ نے زکاۃ کو فرض لازم قرار دیا تو اپنی شان کریمی سے اس کے فیوض و برکات بھی بتلا دیے۔ زکاۃ کی مد میں جو اصل روح کام کر رہی ہے وہ یہ ہے کہ معاشرہ پاکیزہ بن جائے۔ کوئی کسی کا محتاج نہ رہے۔ اسلامی ریاست","",{"v":500109,"fn":"(1) التوبۃ 9:34\n(2) صحیح البخاری: 1395\n(3) التوبۃ 9:60"}],[2180,"کے ہر شہری کو باعزت زندگی بسر کرنے کے وسائل میسر آ جائیں۔ اس طرح خوشحالی کی روشنی پھیلے گی، مسلمانوں کی اجتماعی زندگی کی استعداد توانا ہوگی اور بحیثیت جماعت مسلمانوں پر کبھی اضمحلال طاری نہیں ہوگا۔ یہ وہ صورتحال ہوگی جسے اللہ رب العزت نے اپنے رحم اور کرم سے تعبیر کیا ہے۔ ارشاد ربانی ہے:\n﴿وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللهَ وَرَسُولَهُ أُولَئِكَ سَيَرْحَمُهُمُ اللهُ﴾\n’’مومن مرد اور مومن عورتیں آپس میں ایک دوسرے کے مددگار ہیں۔ وہ نیکی کا حکم دیتے ہیں اور برائی سے روکتے ہیں اور نماز قائم کرتے ہیں اور زکاۃ دیتے ہیں اور اللہ اور اس کے رسول کی اطاعت کرتے ہیں۔ یہی لوگ ہیں جن پر اللہ عنقریب رحم فرمائے گا۔‘‘(1)\nایک اور جگہ فرمایا:\n﴿وَالَّذِينَ هُمْ لِلزَّكَاةِ فَاعِلُونَ﴾\n’’اور (مومن وہ ہیں) جو زکاۃ ادا کرنے والے ہیں۔‘‘(2)\nاللہ تبارک و تعالیٰ نے زکاۃ ادا کرنے والوں کے لیے اپنی رحمت واسعہ کا اعلان فرمایا ہے:\n﴿وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ الزَّكَاةَ وَالَّذِينَ هُمْ بِآيَاتِنَا يُؤْمِنُونَ﴾\n’’اور میری رحمت نے ہر چیز کو گھیر رکھا ہے، چنانچہ جلد ہی میں اس (رحمت) کو ان لوگوں کے لیے لکھ دوں گا جو پرہیزگار ہیں اور زکاۃ دیتے ہیں اور (ان کے لیے بھی) جو ہماری آیتوں پر ایمان لاتے ہیں۔‘‘(3)\nزکاۃ دینے سے مال میں اضافہ ہوتا ہے۔ ارشاد باری تعالیٰ ہے:\n﴿وَمَا آتَيْتُمْ مِنْ زَكَاةٍ تُرِيدُونَ وَجْهَ اللهِ فَأُولَئِكَ هُمُ الْمُضْعِفُونَ﴾\n’’اور تم اللہ کا چہرہ چاہتے ہوئے جو کچھ بطور زکاۃ دیتے ہو، پس ایسے لوگ ہی (اپنا مال) کئی گنا بڑھانے والے ہیں۔‘‘(4)\n§امیر لوگ صدقات و خیرات کو معمول بنائیں\nاسلام نے زکاۃ کے علاوہ متمول افراد کو صدقات کی شکل میں بھی غریبوں اور ناداروں کی امداد کرنے کی ترغیب","",{"v":500110,"fn":"(1) التوبۃ 9:71\n(2) المؤمنون 23:4\n(3) الاعراف 7:156\n(4) الروم 30:39"}],[2181,"دی ہے۔ قرآن مجید میں حکم الہی ہے:\n﴿وَأَنْفِقُوا فِي سَبِيلِ اللهِ وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ﴾\n’’اور تم اللہ کی راہ میں خرچ کرو اور اپنے ہاتھوں ہلاکت (کے کام) میں نہ پڑو اور تم نیکی کرو۔‘‘(1)\nاللہ تبارک و تعالیٰ نے فی سبیل اللہ خرچ کرنے کی تاکید فرمائی ہے:\n﴿يَاأَيُّهَا الَّذِينَ آمَنُوا أَنْفِقُوا مِمَّا رَزَقْنَاكُمْ﴾\n’’اے لوگو جو ایمان لائے ہو! ہم نے تمھیں جو کچھ دیا ہے، اس میں سے خرچ کرو۔‘‘(2)\nامیروں کے مال میں محتاجوں کا بھی حصہ ہے۔ یہ غریبوں، محتاجوں، نادار بیواؤں اور یتیموں کا شرعی حق ہے، ارشاد باری تعالیٰ ہے:\n﴿وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِ وَالْمَحْرُومِ﴾\n’’اور ان کے مالوں میں سوالی اور محروم (نہ مانگنے والے) شخص کا حق (حصہ) ہوتا تھا۔‘‘(3)\nاسلام نے عزیز و اقارب اور مسافروں کی امداد کا حکم دیا ہے۔ تا کہ معاشرے میں محبت اور رواداری کی اجتماعی شکل و صورت سامنے آئے اور من حیث القوم مسلمان ترقی یافتہ ہوں۔ فرمان ربانی ہے:\n﴿فَآتِ ذَا الْقُرْبَى حَقَّهُ وَالْمِسْكِينَ وَابْنَ السَّبِيلِ﴾\n’’لہذا آپ قرابت دار کو اس کا حق دیں اور مسکین اور مسافر کو بھی۔‘‘(4)\nانسان کے دل میں جس چیز کی محبت زیادہ ہوتی ہے اسے سینت سینت کر رکھتا ہے اور جو چیز اس کے لیے معمولی ہوتی ہے اسے ردی خیال کرتا ہے، اللہ تبارک و تعالیٰ نے صدقات و خیرات کی مد میں پاکیزہ مال خرچ کرنے کا حکم دیا ہے، فرمان الہی ہے:\n﴿يَاأَيُّهَا الَّذِينَ آمَنُوا أَنْفِقُوا مِنْ طَيِّبَاتِ مَا كَسَبْتُمْ﴾\n’’اے لوگو جو ایمان لائے ہو! تم ان پاکیزہ چیزوں میں سے خرچ کرو جو تم کماتے ہو۔‘‘(5)\n2 عشور\nاصطلاح میں عشور دو طرح کا ہے: ایک عشور زکاۃ جو غلے، پھل اور اناج جیسی زرعی پیداوار پر عائد ہوتا ہے۔","",{"v":500111,"fn":"(1) البقرۃ 2:195\n(2) البقرۃ 2:254\n(3) الذاریات 51:19\n(4) الروم 30:38\n(5) البقرۃ 2:267"}],[2182,"دوسرا وہ عشور جو بلاد اسلام میں ایک شہر سے دوسرے شہر نقل و حمل کے دوران میں کفار کے اموال پر عائد کیا جاتا ہے۔ اسے عشور کا نام اس لیے دیا گیا کہ اس کی مقدار عشر، یعنی دس گنا یا نصف عشر، یعنی بیس گنا ہوتی ہے۔(1)\n3 مال غنیمت\nریاست مدینہ کے بیت المال میں مال غنیمت بھی جمع ہوتا تھا۔ یہ ایک ہنگامی اور اتفاقی آمدنی تھی جو میدان جنگ میں بزور قوت حاصل ہوتی تھی۔ عہد نبوی میں غنیمت کی سب سے پہلی آمدنی سریہ عبداللہ بن جحش میں ہوئی۔ لیکن اسے رسول اللہ صلی اللہ علیہ وسلم نے قبول نہیں فرمایا۔ غنیمت کی باضابطہ آمدنی جنگ بدر میں ہوئی۔ کفار کے ساتھ جنگ میں ہر قسم کے مال و زر کے علاوہ قیدی بھی آتے تھے جن میں غلام اور لونڈیاں ہوتی تھیں۔ زمانہ جاہلیت میں اہل عرب کی جنگوں میں غنیمت تمام شرکاء میں تقسیم ہوتی تھی لیکن غالب حصہ سردار قبیلہ ہی وصول کرتا تھا۔ نبی صلی اللہ علیہ وسلم نے بدر میں اسے تمام شرکاء میں تقسیم کرنے کا حکم دیا۔\nخمس: جنگ بدر کے بعد قرآنی تعلیم کے مطابق خمس (پانچواں حصہ) علیحدہ کر کے اسے نبی اکرم صلی اللہ علیہ وسلم کے لیے خاص کر دیا گیا۔ فرمان الہی ہے:\n﴿وَاعْلَمُوا أَنَّمَا غَنِمْتُمْ مِنْ شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ﴾\n’’اور (اے مسلمانو!) جان لو کہ تم جو کچھ بھی مال غنیمت حاصل کرو، اس میں سے پانچواں حصہ یقیناً اللہ کے لیے ہے اور رسول کے لیے اور (اس کے) رشتے داروں، یتیموں، مسکینوں اور مسافروں کے لیے ہے۔‘‘(2)\nاسی خمس میں سے نبی صلی اللہ علیہ وسلم کچھ حصہ یتیموں، مسکینوں، مسافروں اور اپنے رشتے داروں کو مرحمت فرما دیتے تھے۔ یوں آپ صلی اللہ علیہ وسلم کے پاس خمس کا تھوڑا سا حصہ ہی بچتا تھا۔\n4 مال فے\nریاست نبوی کی آمدنی کا ایک بڑا ذریعہ مال فے بھی تھا۔ فے سے مراد وہ مفتوحہ اموال و جائیداد ہیں جو بغیر جنگ اور فوج کشی کے براہ راست مسلمانوں کی ملکیت میں آ جائیں۔ رسول اللہ صلی اللہ علیہ وسلم نے 4ھ میں یہود بنو نضیر کو جلا وطن کیا تو ان لوگوں کے باغات اور کھیت رسول اللہ صلی اللہ علیہ وسلم کے قبضے میں آ گئے۔ اسی طرح 5ھ میں یہود بنو قریظہ کا مال و اسباب اور علاقہ ہاتھ آیا۔ نیز خیبر کے قریب کئی علاقے بغیر جنگ کے رسول اللہ صلی اللہ علیہ وسلم کو مل گئے۔ رسول اللہ صلی اللہ علیہ وسلم","",{"v":500112,"fn":"(1) المغنی: 516/8، الکافی لابن عبد البر: 480/1، الموسوعۃ الفقہیۃ: 153/15\n(2) الانفال 8:41"}],[2183,"مال فے بیت المال میں جمع کرا دیتے اور اپنی صوابدید کے مطابق جس طرح مناسب خیال فرماتے، خرچ کرتے تھے۔ قرآن مجید میں ارشاد ہے:\n﴿وَمَا أَفَاءَ اللهُ عَلَى رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَكِنَّ اللهَ يُسَلِّطُ رُسُلَهُ عَلَى مَنْ يَشَاءُ وَاللهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾\n’’اور اللہ نے ان (یہود) سے اپنے رسول کی طرف جو مال لوٹایا، اس کے لیے تم نے گھوڑے اور اونٹ نہیں دوڑائے لیکن اللہ اپنے رسولوں کو جس پر چاہتا ہے غلبہ دیتا ہے۔ اور اللہ ہر چیز پر خوب قادر ہے۔‘‘(1)\n5 خراج\nیہ وہ محصول اراضی ہے جو غیر مسلموں سے وصول کیا جاتا تھا۔ یہ سب سے پہلے خیبر سے حاصل ہوا۔ فتح خیبر کے وقت مسلمانوں کے پاس اتنے وسائل نہ تھے کہ وہ مفتوحہ زمینوں کی دیکھ بھال اور کاشت وغیرہ کر سکتے۔ دوسری طرف یہود نے از خود یہ پیشکش کی تھی کہ وہ ریاست نبوی کے مزارع کی حیثیت سے اس زمین پر کاشت کریں گے، اس لیے رسول اللہ صلی اللہ علیہ وسلم نے ان کی پیشکش قبول کرتے ہوئے پیداوار کا نصف بطور خراج مقرر فرما دیا۔ خراج کی رقم بیت المال میں جمع ہوتی اور وہاں سے مجاہدین کی تنخواہوں اور دیگر عمومی ضروریات پر خرچ کی جاتی تھی۔\n6 جزیہ\nاسلامی سلطنت میں جزیہ وہ محصول تھا جو غیر مسلموں سے ان کی جان، مال اور آبرو کی حفاظت اور عقیدے، رائے اور ضمیر کی آزادی اور فوجی خدمت سے استثنا کے بدلے میں وصول کیا جاتا تھا۔ یہ صرف مردوں پر لاگو تھا۔ عورتیں اور بچے اس سے مستثنیٰ تھے۔ اسی طرح کام کاج سے معذور بوڑھوں اور مفلسوں پر بھی جزیہ عائد نہیں تھا۔ مفلوج اور راہب بھی اس سے مستثنیٰ تھے۔ اس کے بدلے میں وہ عبادت اور معیشت و معاشرت کے تمام حقوق سے بہرہ ور ہوتے تھے۔ خراج زمین پر اور جزیہ افراد و اشخاص پر عائد کیا جاتا ہے۔\n[تصویر: علاقہ خیبر کا ایک منظر]","",{"v":500113,"fn":"(1) الحشر 59:6","im":["v5_p113.jpg"]}],[2184,"§اولین مملکت اسلامیہ کے چیف جسٹس\nاسلامی ریاست مدینہ میں نبی صلی اللہ علیہ وسلم مختلف اقوام و مذاہب کے حکمران اور قاضی القضاۃ (چیف جسٹس) تھے۔ آپ صلی اللہ علیہ وسلم مملکت اسلامیہ کے تمام باشندوں سے یکساں طور پر عدل و انصاف فرماتے تھے۔ تمام ریاستی باشندے آپ صلی اللہ علیہ وسلم کے فیصلوں کو بے چون و چرا نہایت خوش دلی سے تسلیم کرتے تھے یہاں تک کہ میثاق مدینہ میں یہ شق بھی شامل تھی: جب بھی تم میں کسی امر کے متعلق اختلاف رونما ہو تو اللہ اور محمد رسول اللہ صلی اللہ علیہ وسلم سے رجوع کیا جائے گا۔\n§رسول اللہ صلی اللہ علیہ وسلم کے فیصلے کو خوش دلی سے قبول کرنے کا حکم\nقرآن مجید نے بھی آپ صلی اللہ علیہ وسلم ہی کے فیصلے کو حتمی قول فیصل ٹھہرایا ہے اور اسے دل و جان سے قبول کرنے کا حکم دیا ہے، فرمان الہی ہے:\n﴿فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا فِي أَنْفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا﴾\n’’چنانچہ (اے نبی!) آپ کے رب کی قسم! وہ مومن نہیں ہو سکتے جب تک کہ اپنے باہمی اختلافات میں آپ کو فیصلہ کرنے والا نہ مان لیں، پھر آپ کے کیے ہوئے فیصلے پر ان کے دلوں میں کوئی تنگی نہ آنے پائے اور وہ اسے دل و جان سے مان لیں۔‘‘(1)\n§رسول اللہ صلی اللہ علیہ وسلم کا فیصلہ انصاف کی معراج ہے\nسیدنا عروہ رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا زبیر رضی اللہ عنہ کا ایک انصاری سے حرہ کی ندی کے پانی کے بارے میں جھگڑا ہوا تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:\n﴿اسْقِ يَا زُبَيْرُ ثُمَّ أَرْسِلِ الْمَاءَ إِلَى جَارِكَ﴾\n[تصویر: قلعہ عروہ بن زبیر کے آثار (مدینہ منورہ)]","",{"v":500114,"fn":"(1) النساء 4:65","im":["v5_p114.jpg"]}],[2185,"’’زبیر! تم (اپنی کھیتی کو) پانی دے لیا کرو، پھر پانی اپنے پڑوسی کی طرف روانہ کر دیا کرو۔‘‘\nانصاری نے کہا: اللہ کے رسول! آپ نے یہ فیصلہ اس لیے فرمایا ہے کہ زبیر آپ کے پھوپھی زاد ہیں۔ یہ سن کر آپ صلی اللہ علیہ وسلم کے چہرہ مبارک کا رنگ متغیر ہو گیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿اسْقِ يَا زُبَيْرُ ثُمَّ احْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ، ثُمَّ أَرْسِلِ الْمَاءَ إِلَى جَارِكَ﴾\n’’زبیر! (اپنی کھیتی کو) پانی دو، پھر پانی کو روک لو یہاں تک کہ وہ منڈیروں تک آ جائے، پھر اپنے پڑوسی کے لیے پانی چھوڑ دو۔‘‘\n[تصویر: برکہ زبیر بن عوام رضی اللہ عنہ، مدینہ منورہ]\nاس طرح انصاری کی طرف سے نبی صلی اللہ علیہ وسلم کو ناراض کرنے کے بعد آپ صلی اللہ علیہ وسلم نے اپنے صریح حکم کے مطابق زبیر رضی اللہ عنہ کو اختیار دیا کہ وہ اپنا حق پورا پورا وصول کر لیں، حالانکہ اس سے پہلے آپ نے جو صورت پیش فرمائی تھی اس میں دونوں کے لیے سہولت تھی۔ زبیر رضی اللہ عنہ فرماتے ہیں کہ میرا خیال ہے کہ درج بالا آیت کریمہ اسی موقع پر نازل ہوئی تھی۔(1)\n§رسول اللہ صلی اللہ علیہ وسلم کا فیصلہ نہ ماننے والے کا انجام\nبیان کیا گیا ہے کہ ایک دفعہ دو آدمی آپس میں جھگڑ پڑے۔ دونوں نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ آپ صلی اللہ علیہ وسلم نے ایک کے حق میں فیصلہ دے دیا۔ دوسرا مطمئن نہ ہوا۔ اس نے کہا کہ میں عمر رضی اللہ عنہ کے پاس جاتا ہوں","",{"v":500115,"fn":"(1) صحیح البخاری: 4585","im":["v5_p115.jpg"]}],[2186,"تا کہ وہ میرے معاملے میں فیصلہ کریں۔ وہ دونوں سیدنا عمر رضی اللہ عنہ کے پاس پہنچے۔ سیدنا عمر رضی اللہ عنہ کو واقعے کی خبر دی گئی۔ جس کے حق میں نبی صلی اللہ علیہ وسلم نے فیصلہ دیا تھا، وہ کہنے لگا: اے عمر! فیصلہ سنانے سے پہلے یہ بات سن لو کہ نبی صلی اللہ علیہ وسلم نے میرے حق میں فیصلہ دے دیا ہے۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: ٹھہرو! میں ابھی آتا ہوں۔ یہ کہہ کر گھر گئے اور تلوار نکال لائے اور جس شخص نے آپ صلی اللہ علیہ وسلم کے فیصلے کو نہیں مانا تھا، اسے قتل کر دیا۔ یہ معاملہ نبی صلی اللہ علیہ وسلم تک پہنچا تو اللہ تبارک و تعالیٰ نے مذکورہ بالا آیت نازل فرما دی۔(1)\n§انصاف کے تقاضے پورے کرنے کا حکم\nقرآن میں اللہ تعالیٰ کی وحدانیت کے اقرار اور شرک کی مذمت کے بعد سب سے زیادہ عدل کے تقاضے پورے کرنے پر زور دیا گیا ہے۔ اس کا مقصد بنی نوع انسان کے حقوق کا تحفظ ہے۔ اللہ تعالیٰ کا فرمان ہے:\n﴿يَاأَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ لِلَّهِ شُهَدَاءَ بِالْقِسْطِ وَلَا يَجْرِمَنَّكُمْ شَنَآنُ قَوْمٍ عَلَى أَلَّا تَعْدِلُوا اعْدِلُوا هُوَ أَقْرَبُ لِلتَّقْوَى وَاتَّقُوا اللهَ إِنَّ اللهَ خَبِيرٌ بِمَا تَعْمَلُونَ﴾\n’’اے ایمان والو! اللہ کی خاطر خوب قائم رہنے والے، انصاف کے ساتھ گواہی دینے والے بن جاؤ اور کسی قوم کی دشمنی تمھیں ہرگز اس بات پر آمادہ نہ کرے کہ تم عدل نہ کرو۔ عدل کرو، یہ تقویٰ کے زیادہ قریب ہے اور اللہ سے ڈرو۔ بے شک اللہ اس سے پوری طرح باخبر ہے جو تم کرتے ہو۔‘‘(2)\nپچھلی تمام امتوں میں بھی عدل و انصاف کو بڑی اہمیت دی گئی۔ فرمان الہی ہے:\n﴿يَادَاوُدُ إِنَّا جَعَلْنَاكَ خَلِيفَةً فِي الْأَرْضِ فَاحْكُمْ بَيْنَ النَّاسِ بِالْحَقِّ﴾\n’’(ہم نے کہا:) اے داود! بے شک ہم نے تجھے زمین میں خلیفہ بنایا ہے، لہذا تو لوگوں کے درمیان انصاف سے فیصلہ کر۔‘‘(3)\n§بے لاگ فیصلہ کرنے والا جج جنتی ہے\nنبی صلی اللہ علیہ وسلم کے دور میں اسلامی سلطنت پورے جزیرہ نمائے عرب میں پھیل چکی تھی۔ اس میں مسلمانوں کے علاوہ دیگر مذاہب کے لوگ بھی موجود تھے۔ لیکن آپ صلی اللہ علیہ وسلم نے کسی کافر کو کبھی قاضی مقرر نہیں فرمایا بلکہ جتنے بھی قاضی تھے، وہ سب آزاد مسلمان مرد تھے۔ قاضی کو انتہائی منصف ہونا چاہیے کیونکہ یہ بہت بڑی ذمہ داری ہے۔ بریدہ بن","",{"v":500116,"fn":"(1) تفسیر ابن کثیر، تفسیر ابن ابی حاتم، النساء 4:65، الصارم المسلول، ص: 38\n(2) المائدۃ 5:8\n(3) ص 38:26"}],[2187,"حصیب رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے بیان کرتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿الْقُضَاةُ ثَلَاثَةٌ، وَاحِدٌ فِي الْجَنَّةِ، وَاثْنَانِ فِي النَّارِ، فَأَمَّا الَّذِي فِي الْجَنَّةِ فَرَجُلٌ عَرَفَ الْحَقَّ فَقَضَى بِهِ، وَرَجُلٌ عَرَفَ الْحَقَّ فَجَارَ فِي الْحُكْمِ فَهُوَ فِي النَّارِ، وَرَجُلٌ قَضَى لِلنَّاسِ عَلَى جَهْلٍ فَهُوَ فِي النَّارِ﴾\n’’تین قسم کے قاضی ہوں گے، ایک جنت میں اور دو جہنم میں جائیں گے۔ جنت میں جانے والا وہ شخص ہے جس نے حق کو پہچان لیا اور اس پر فیصلہ صادر کر دیا، لیکن وہ شخص جس نے حق کو جانا اور فیصلے میں ظلم کیا، وہ دوزخ میں جائے گا، اور تیسرا وہ شخص ہے جو کچھ جانے بوجھے بغیر ہی لوگوں میں فیصلہ کر دے، وہ بھی دوزخ میں جائے گا۔‘‘(1)\n§جج کے فضائل و مراتب اور آزمائشیں\nہمارا مقدس دین ہر مسلمان کو ہر حال میں ’’قول سدید‘‘ کہنے اور عدل کرنے کی تاکید فرماتا ہے۔ اس اعتبار سے اندازہ کیا جا سکتا ہے کہ دین متین کے نزدیک ایک جج کے فرائض کتنے کڑے اور فضائل کس قدر رفیع الشان ہوں گے۔ درج ذیل احادیث مبارک میں جج کی نازک ذمہ داریوں اور اس کے اجر و ثواب کی تفصیلات بیان کی گئی ہیں۔ سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: میں نے نبی صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے:\n﴿يُدْعَى بِالْقَاضِي الْعَادِلِ يَوْمَ الْقِيَامَةِ، فَيَلْقَى مِنْ شِدَّةِ الْحِسَابِ مَا يَتَمَنَّى أَنَّهُ لَمْ يَقْضِ بَيْنَ اثْنَيْنِ فِي عُمُرِهِ﴾\n’’عادل قاضی کو قیامت کے دن طلب کیا جائے گا۔ اس کا اتنا کڑا حساب ہوگا کہ وہ تمنا کرے گا کاش! اس نے پوری زندگی کسی دو آدمیوں کے درمیان فیصلہ نہ کیا ہوتا۔‘‘(2)\nسیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿مَنْ وَلِيَ الْقَضَاءَ، أَوْ جُعِلَ قَاضِيًا بَيْنَ النَّاسِ فَقَدْ ذُبِحَ بِغَيْرِ سِكِّينٍ﴾\n’’جسے منصب قضا مل گیا یا اسے لوگوں کے درمیان قاضی بنا دیا گیا، بلاشبہ وہ بغیر چھری کے ذبح ہو گیا۔‘‘(3)","",{"v":500117,"fn":"(1) سنن ابی داود: 3573، جامع الترمذی: 1322، سنن ابن ماجہ: 2315\n(2) مسند احمد: 75/6، صحیح ابن حبان: 439/11، حدیث: 5055\n(3) سنن ابی داود: 3571,3572، جامع الترمذی: 1325"}],[2188,"دوسری جانب عادل جج کی فضیلت اور اس کے منصب کی عظمت بھی بہت بلند پایہ ہے۔ تمام انبیاء علیہم السلام قاضی تھے۔ قیامت کے دن عادل قاضی کا بہت اعلیٰ مرتبہ ہو گا۔ عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں، نبی صلی اللہ علیہ وسلم نے فرمایا:\n﴿لَا حَسَدَ إِلَّا فِي اثْنَتَيْنِ: رَجُلٌ آتَاهُ اللهُ مَالًا فَسُلِّطَ عَلَى هَلَكَتِهِ فِي الْحَقِّ، وَرَجُلٌ آتَاهُ اللهُ الْحِكْمَةَ، فَهُوَ يَقْضِي بِهَا وَيُعَلِّمُهَا﴾\n’’حسد جائز نہیں مگر دو آدمیوں کے بارے میں، پہلا شخص وہ ہے جسے اللہ نے مال دیا اور وہ اسے راہ حق میں خرچ کرنے پر بھی قدرت رکھتا ہے اور دوسرا شخص وہ جسے اللہ نے حکمت سے نوازا اور وہ اس کے ذریعے سے فیصلے کرتا ہے اور (لوگوں کو) اس کی تعلیم دیتا ہے۔‘‘(1)\nسیدہ عائشہ رضی اللہ عنہا فرماتی ہیں، نبی صلی اللہ علیہ وسلم نے فرمایا:\n﴿أَتَدْرُونَ مَنِ السَّابِقُونَ إِلَى ظِلِّ اللهِ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ؟﴾\n’’کیا تمھیں معلوم ہے قیامت کے روز اللہ کے سائے میں سبقت لے جانے والے کون ہوں گے؟‘‘ صحابہ کہنے لگے: اللہ اور اس کا رسول ہی بہتر جانتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿الَّذِينَ إِذَا أُعْطُوا الْحَقَّ قَبِلُوهُ، وَإِذَا سُئِلُوا بَذَلُوهُ، وَحَكَمُوا لِلنَّاسِ كَحُكْمِهِمْ لِأَنْفُسِهِمْ﴾\n’’یہ وہ لوگ ہوں گے کہ جب انھیں حق دیا جائے تو وہ قبول کر لیتے ہیں، جب ان سے سوال کیا جائے تو وہ خرچ کرتے ہیں اور لوگوں میں اسی طرح فیصلے کرتے ہیں جس طرح وہ خود اپنے لیے فیصلے کرتے ہیں۔‘‘(2)\nسیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\n﴿الْعَدْلُ الْعَامِلُ فِي رَعِيَّتِهِ يَوْمًا وَاحِدًا أَفْضَلُ مِنْ عِبَادَةِ الْعَابِدِ فِي أَهْلِهِ مِائَةَ عَامٍ أَوْ خَمْسِينَ عَامًا﴾\n’’عامل کا اپنی رعیت میں ایک دن کا عدل عابد کی اپنے گھر میں سو سال یا پچاس سال کی عبادت سے افضل ہے۔‘‘(3)\n§مجاز حکام اور ججوں کا تقرر\nجب اسلام اطراف و اکناف میں پھیل گیا اور قبائل کے وفود آنے لگے تو صدقات و زکاۃ کی وصولی بھی شروع","",{"v":500118,"fn":"(1) صحیح البخاری: 73\n(2) مسند احمد: 67/6، یہ روایت ضعیف ہے\n(3) المطالب العالیۃ: 232/2، روایت ضعیف ہے"}],[2189,"[تصویر: نقشہ: نبی صلی اللہ علیہ وسلم کے مامور امراء]\nنقشے کے اہم مقامات: تیماء، تبوک، مدینہ منورہ، الاحساء، دارین، عمان، خلیج فارس، فارس، جزیرہ نماۓ عرب، الربع الخالی، نجران، حضرموت، یمن، جند، عدن، بحیرہ عرب، بحیرہ قلزم (بحیرہ احمر)، قرن افریقہ، حبشہ، جدہ\nنبی صلی اللہ علیہ وسلم کے مامور امراء: 1۔ صنعاء: بازان رضی اللہ عنہ، شہر بن باذان رضی اللہ عنہ، خالد بن سعید رضی اللہ عنہ 2۔ حضرموت: زیاد بن لبید رضی اللہ عنہ 3۔ زبید و عدن: ابوموسیٰ اشعری رضی اللہ عنہ 4۔ جند (تعز): معاذ بن جبل رضی اللہ عنہ 5۔ نجران: ابوسفیان بن حرب رضی اللہ عنہ 6۔ تیماء: یزید بن ابی سفیان رضی اللہ عنہ 7۔ عمان: عمرو بن العاص رضی اللہ عنہ\nہوگئی۔ آپ صلی اللہ علیہ وسلم نے مختلف علاقوں میں مبلغین، گورنر اور قاضی مقرر فرمائے، یہ سب صحابہ کرام رضی اللہ عنہم بڑے اجل عالم تھے۔ مقدمات کا بے لاگ فیصلہ کرتے تھے۔ سب سے پہلے وہ اسلام کی تبلیغ کرتے تھے، اسلامی تعلیمات سے روشناس کراتے تھے۔ محاصل زکاۃ مدینہ پہنچاتے تھے۔ ذاتی اور معاشرتی جھگڑوں اور جملہ تنازعات میں احکام اسلام کے مطابق فیصلے کرتے تھے اور اللہ کی حدود قائم کرتے تھے۔ لوگوں کو ان کے حقوق ادا کراتے تھے تاکہ کوئی غاصب کسی کمزور آدمی کا حق نہ مار سکے۔ شریعت محمدی کے مطابق سادہ زندگی بسر کرتے تھے اور لوگوں کو اطاعت بالمعروف اور نہی عن المنکر کا درس دیتے تھے۔\nآپ صلی اللہ علیہ وسلم نے جن اصحاب کو مختلف علاقوں میں قاضی اور عامل مقرر فرمایا، غور فرمائیں کہ وہ کتنے اجل عالم اور بلند پایہ لوگ تھے:\n§سیدنا علی بن ابی طالب رضی اللہ عنہ\nنبی صلی اللہ علیہ وسلم کے گھر میں پرورش پانے والے اور بچوں میں سب سے پہلے اسلام لانے والے آپ کے چچیرے بھائی اور داماد سیدنا علی رضی اللہ عنہ فرماتے ہیں: نبی صلی اللہ علیہ وسلم نے مجھے یمن کی جانب قاضی بنا کر بھیجا، میں نے کہا: اے اللہ کے رسول! آپ مجھے بھیج تو رہے ہیں لیکن میں پختہ عمر ہوں نہ مقدمات کے فیصلے کرنا جانتا ہوں۔ آپ نے فرمایا:","",{"v":500119,"im":["v5_p119.jpg"]}],[2190,"«إِنَّ اللهَ سَيَهْدِي قَلْبَكَ وَيُثَبِّتُ لِسَانَكَ فَإِذَا جَلَسَ بَيْنَ يَدَيْكَ الْخَصْمَانِ فَلَا تَقْضِيَنَّ حَتَّى تَسْمَعَ مِنَ الْآخَرِ كَمَا سَمِعْتَ مِنَ الْأَوَّلِ فَإِنَّهُ أَخْرَى أَنْ يَتَبَيَّنَ لَكَ الْقَضَاءُ»\n’’عنقریب اللہ تمھارے دل کی راہنمائی (شرح صدر) فرمائے گا اور تمھاری زبان کو ثابت رکھے گا۔ جب تمھارے سامنے دو جھگڑنے والے پیش ہوں تو اس وقت تک فیصلہ نہ کرنا جب تک دوسرے فریق کی بات بھی اسی طرح نہ سن لو جس طرح پہلے فریق کی بات سنی تھی۔ اس طرح تمھیں فیصلہ کرنے میں واضح رہنمائی میسر آئے گی۔‘‘\n§سیدنا معاذ بن جبل رضی اللہ عنہ\nآپ صلی اللہ علیہ وسلم کے صحابی معاذ بن جبل رضی اللہ عنہ حلال و حرام کا سب سے زیادہ علم رکھنے والے تھے۔ طبقات ابن سعد میں کعب بن مالک رضی اللہ عنہ سے روایت ہے کہ معاذ بن جبل رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کی مبارک زندگی میں اور پھر ابوبکر رضی اللہ عنہ کی خلافت میں مدینے کے مفتی تھے۔ آپ صلی اللہ علیہ وسلم نے انھیں یمن کی طرف قاضی بنا کر روانہ فرمایا۔ روانگی کے وقت آپ صلی اللہ علیہ وسلم نے سیدنا معاذ رضی اللہ عنہ سے پوچھا: «كَيْفَ تَقْضِي إِذَا عَرَضَ لَكَ قَضَاءٌ؟» ‘‘جب تم کسی معاملے کا فیصلہ کرو گے تو کیا طریق کار اختیار کرو گے؟‘‘ انھوں نے عرض کیا: میں اللہ کی کتاب کے مطابق فیصلہ کروں گا۔ آپ صلی اللہ علیہ وسلم نے دریافت فرمایا: «فَإِنْ لَمْ تَجِدْ فِي كِتَابِ اللهِ؟» ‘‘اگر تم اللہ کی کتاب میں نہ پائے تو کیا کرو\n1۔ سنن أبي داود: 3582، جامع الترمذي: 1331، سنن ابن ماجه: 2310\n[تصویر: سیدنا معاذ بن جبل رضی اللہ عنہ کے عہد کی قدیم مسجد: جامع الجند (یمن)]","",{"v":500120,"im":["v5_p120.jpg"]}],[2191,"گے؟ عرض کیا: میں سنت رسول اللہ صلی اللہ علیہ وسلم کے مطابق فیصلہ کروں گا۔ آپ صلی اللہ علیہ وسلم نے پھر پوچھا: «فَإِنْ لَمْ تَجِدْ فِي سُنَّةِ رَسُولِ اللهِ وَلَا فِي كِتَابِ اللهِ؟» ’’اگر تم نے اللہ کے رسول صلی اللہ علیہ وسلم کی سنت میں بھی نہ پایا اور اللہ کی کتاب میں بھی نہ ملا (تب کیا کرو گے؟)‘‘ معاذ رضی اللہ عنہ نے عرض کیا: میں اس صورت میں اپنی فراست سے بھرپور اجتہاد کروں گا۔ آپ صلی اللہ علیہ وسلم نے معاذ رضی اللہ عنہ کے سینے پر ہاتھ مارا اور فرمایا: «الْحَمْدُ لِلَّهِ الَّذِي وَفَّقَ رَسُولَ رَسُولِ اللهِ لِمَا يُرْضِي رَسُولَ اللهِ» ’’اللہ کا بے حد شکر ہے جس نے اپنے رسول کے نمائندے کو اس چیز کی توفیق دی جس سے اللہ کے رسول راضی ہو گئے۔‘‘(1)\n§سیدنا علاء بن حضرمی رضی اللہ عنہ\nرسول اللہ صلی اللہ علیہ وسلم نے انھیں بحرین کا قاضی مقرر فرمایا اور ان کے لیے اہل بحرین کے نام ایک وثیقہ تحریر کرایا جسے معاویہ بن ابی سفیان رضی اللہ عنہ نے لکھا۔ اس طویل خط میں یہ عبارت بھی درج تھی:\n«اتَّقُوا اللهَ أَيُّهَا الْمُسْلِمُونَ مَا اسْتَطَعْتُمْ، فَإِنِّي قَدْ بَعَثْتُ عَلَيْكُمُ الْعَلَاءَ بْنَ الْحَضْرَمِيِّ وَأَمَرْتُهُ أَنْ يَتَّقِيَ اللهَ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنْ يُلِينَ لَكُمُ الْجَنَاحَ، وَيُحْسِنَ فِيكُمُ السِّيرَةَ بِالْحَقِّ، وَيَحْكُمَ بَيْنَكُمْ وَبَيْنَ مَنْ لَقِيَ مِنَ النَّاسِ بِمَا أَنْزَلَ اللهُ عَزَّ وَجَلَّ فِي كِتَابِهِ مِنَ الْعَدْلِ، وَأَمَرْتُكُمْ بِطَاعَتِهِ إِذَا فَعَلَ ذَلِكَ....»\n’’اے مسلمانو! حسب استطاعت اللہ سے ڈرو۔ میں تمھاری طرف علاء بن حضرمی کو بھیج رہا ہوں۔ میں نے انھیں حکم دیا ہے کہ اللہ وحدہ لاشریک سے ڈریں اور تمھارے لیے نرم گوشہ رکھیں۔ تمھارے ساتھ حق اور بھلائی سے چلیں، لوگوں کے اور تمھارے درمیان جس طرح اللہ نے اپنی کتاب میں نازل فرمایا ہے، اس کے مطابق عدل و انصاف\n[تصویر: مسجد علاء بن حضرمی (رضی اللہ عنہ)، بحرین]","",{"v":500121,"fn":"(1) سنن أبي داود: 3592، جامع الترمذي: 1327۔ السلسلة الضعيفة: 881","im":["v5_p121.jpg"]}],[2192,"کریں۔ جب یہ اس طرح کریں تو میں تمھیں ان کی اطاعت کا حکم دیتا ہوں۔‘‘(1)\n§سیدنا معقل بن سیار مزنی رضی اللہ عنہ\nیہ بھی رسول اللہ صلی اللہ علیہ وسلم کے مقرر کردہ جج تھے۔ یہ بھی بتاتے ہیں: مجھے نبی صلی اللہ علیہ وسلم نے حکم دیا کہ میں اپنی قوم کے مابین فیصلے کروں۔ میں نے عرض کیا: اے اللہ کے رسول! میں کوئی بہت اچھا جج نہیں ہوں۔ آپ نے فرمایا: «اللهُ مَعَ الْقَاضِي مَا لَمْ يَحِفْ عَمْدًا» ’’اللہ قاضی کے ساتھ ہوتا ہے جب تک وہ جان بوجھ کر ظلم و ستم نہ کرے۔‘‘(2)\n§سیدنا عمرو بن العاص قرشی رضی اللہ عنہ\nعبداللہ بن عمرو بن العاص رضی اللہ عنہما سے مروی ہے، وہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کے پاس باہم جھگڑنے والے دو افراد آئے۔ آپ صلی اللہ علیہ وسلم نے (میرے والد) عمرو رضی اللہ عنہ سے فرمایا: «اِقْضِ بَيْنَهُمَا يَا عَمْرُو!» ’’اے عمرو! ان کے درمیان فیصلہ کرو۔‘‘ عمرو کہنے لگے: اے اللہ کے رسول! آپ مجھ سے بہت بہتر فیصلہ کر سکتے ہیں۔ آپ نے فرمایا: «وَإِنْ كَانَ» ’’بے شک میں کر سکتا ہوں (لیکن پھر بھی تمھی فیصلہ کرو۔)‘‘ عمرو کہنے لگے: اے اللہ کے رسول! مجھے ان کے درمیان فیصلہ کر کے کیا ملے گا؟ آپ نے فرمایا: «إِنْ أَنْتَ قَضَيْتَ بَيْنَهُمَا فَأَصَبْتَ الْقَضَاءَ فَلَكَ عَشْرُ حَسَنَاتٍ، وَإِنْ أَنْتَ اجْتَهَدْتَ فَأَخْطَأْتَ فَلَكَ حَسَنَةٌ» ’’اگر تم نے ان کے درمیان فیصلہ کیا اور وہ فیصلہ صحیح ہوا تو تمھارے لیے دس نیکیاں ہیں اور اگر تم نے اجتہاد کیا اور اس میں غلطی کر گئے، تب بھی تمھیں ایک نیکی ملے گی۔‘‘(3)\n[تصویر: مسجد عمرو بن العاص (رضی اللہ عنہ)، مصر]","",{"v":500122,"fn":"(1) المطالب العالية: 237-244/2\n(2) مسند أحمد: 26/5، یہ روایت ضعیف ہے تاہم اس کا معنی صحیح ہے۔ دیکھیے: سنن ابن ماجه: 2312\n(3) مسند أحمد: 205/4، یہ روایت ضعیف ہے۔","im":["v5_p122.jpg"]}],[2193,"§سیدنا عقبہ بن عامر رضی اللہ عنہ\nعقبہ بن عامر رضی اللہ عنہ کے بارے میں بھی روایت ہے کہ نبی صلی اللہ علیہ وسلم نے انھیں بھی دو آدمیوں کے مابین فیصلہ کرنے کا حکم دیا۔(1)\n§سیدنا عمر بن خطاب رضی اللہ عنہ بحیثیت قاضی\nخلیفہ ثالث سیدنا عثمان بن عفان رضی اللہ عنہ نے عبداللہ بن عمر رضی اللہ عنہما سے فرمایا: جاؤ لوگوں کے مابین فیصلے کرو۔ وہ کہنے لگے: اے امیر المؤمنین! کیا آپ مجھے اس سلسلے میں معاف نہیں کر سکتے؟ عثمان رضی اللہ عنہ نے فرمایا: تمھیں کیا ہے جبکہ تمھارے والد فیصلے کرتے تھے۔(2)\nابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ عثمان رضی اللہ عنہ نے مجھ سے کہا: تمھیں منصب قضا قبول کرنے میں کون سا امر مانع ہے، حالانکہ تمھارے باپ (عمر رضی اللہ عنہ) رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں فیصلے کرتے تھے تو میں نے جواب دیا: نہ میں اپنے باپ کی طرح ہوں اور نہ آپ رسول اللہ صلی اللہ علیہ وسلم جیسے ہیں۔ میرے والد محترم کو جب فیصلے میں کوئی پیچیدگی پیش آتی تھی تو وہ آپ صلی اللہ علیہ وسلم سے پوچھ لیتے تھے اور جب آپ صلی اللہ علیہ وسلم کو کسی مسئلے میں الجھن ہوتی تو جبریل علیہ السلام سے دریافت کر لیتے تھے۔ (اور وہ وحی کے ذریعے سے بتا دیتے تھے۔)(3)\n[تصویر: مسجد عمر بن خطاب (رضی اللہ عنہ)، دومة الجندل]","",{"v":500123,"fn":"(1) مسند أحمد: 205/4، یہ روایت ضعیف ہے۔\n(2) جامع الترمذي: 1322\n(3) الرياض النضرة في مناقب العشرة: 159/1","im":["v5_p123.jpg"]}],[2194,"§مدینہ منورہ کے مفتیان کرام\nمحمد بن سہل بن ابی حثمہ اپنے والد (سہل رضی اللہ عنہ) سے بیان کرتے ہیں۔ انھوں نے فرمایا: نبی صلی اللہ علیہ وسلم کے دور میں تین مہاجر اور تین انصاری فتوے دیتے تھے۔ مہاجرین میں سے عمر، عثمان، علی رضی اللہ عنہم اور انصار میں سے ابی بن کعب، معاذ اور زید بن ثابت رضی اللہ عنہم مفتی تھے۔\nرسول اللہ صلی اللہ علیہ وسلم نے حذیفہ بن یمان رضی اللہ عنہ کو یمامہ کے ایک باغ کے جھگڑے میں فیصلہ کرنے کا حکم دیا۔ عتاب بن اسید رضی اللہ عنہ کو مکہ میں والی اور قاضی مقرر کیا۔ دحیہ کلبی رضی اللہ عنہ کو یمن کے نواح میں قاضی بنا کر بھیجا اور ابوموسیٰ اشعری رضی اللہ عنہ کو معاذ بن جبل رضی اللہ عنہ کے ساتھ یمن کا قاضی بنا کر روانہ فرمایا۔(1)\n[تصویر: مسجد ابوموسیٰ اشعری (رضی اللہ عنہ)، زبید، یمن]","",{"v":500124,"fn":"(1) أقضية رسول الله: 26-37/1","im":["v5_p124.jpg"]}],[2195,"§اسلامی ریاست کی خارجہ پالیسی\nکسی ریاست یا مملکت کی خارجہ پالیسی بالعموم ریاستی آئین، داخلی احوال، معاشرتی رویوں اور رسوم و رواج کی عکاسی کرتی ہے۔ مملکت کی معاشی پالیسیاں، دو طرفہ قوانین اور فروغ امن کے معاہدے، ثقافتی اور سماجی تعلقات، سیاسی روابط، علوم و فنون کی منتقلی، افرادی قوت، ہنر مندوں اور اہل علم کے تبادلے، اقلیتی حقوق، دفاعی اور حربی مفادات، یہ سب کچھ خارجہ پالیسی کے دائرہ کار میں ہوتا ہے۔ گویا خارجہ پالیسی ریاست اور اس کے شہریوں کے مفادات کا تحفظ کرتی ہے، اس کی سالمیت اور دفاع کو مستحکم بناتی ہے۔ معیشت و معاشرت، تہذیب و تمدن اور باہم لین دین کے امکانات کو فروغ دیتی ہے اور ضرورت پڑنے پر جنگ کے لیے تیار رہنے کی راہ بھی دکھاتی ہے۔\nدور نبوی میں جزیرہ نمائے عرب کے مشرق اور مغرب میں روم و فارس کی دو بڑی سلطنتیں آپس میں برسر پیکار تھیں۔ جنوب مغرب میں سلطنت حبشہ موجود تھی۔ عمان، بحرین اور حیرہ سلطنت فارس کے باجگزار تھے اور غسان سلطنت روم (Byzantine Empire) کی باجگزار ریاست تھی جو موجودہ اردن اور جنوبی شام پر محیط تھی۔ یمن پر براہ راست ایرانی گورنر حکمران تھا جبکہ شاہ مصر مقوقس قیصر روم کا نامزد کردہ تھا۔\n[تصویر: نجاشی کا سکہ]\nجزیرہ نمائے عرب میں جنگجو قبائل کے معاشرے نے بے شمار مذہبی اور معاشرتی امراض پیدا کر دیے تھے۔ اپنی اپنی خواہشات کی تکمیل کی خاطر مختلف قبائل نے الگ الگ بت بنا رکھے تھے۔ معاشرتی برائیوں میں زنا، شراب نوشی اور قمار بازی عام تھی۔ ظلم و ستم کے قصے فخر و غرور سے بیان کیے جاتے تھے اور بات بے بات قتل و غارت گری کا بازار گرم ہو جاتا تھا۔ اسی وجہ سے بازنطینیوں اور ایرانیوں کی نظر میں عرب ایک وحشی قوم تھی۔ رومی مؤرخین انھیں ’’ہلاکت خیز قوم‘‘ (Natio perniciosa) کہتے تھے۔(1)\n[تصویر: خسرو پرویز کا سکہ]","",{"v":500125,"fn":"(1) دیکھیے: رسول اکرم صلی اللہ علیہ وسلم کی سیاست خارجہ، ص: 15","im":["v5_p125.jpg"]}],[2196,"[تصویر: ہرقل کا سکہ]\nرومی سلطنت نبی صلی اللہ علیہ وسلم کے دور میں عروج سے زوال کی طرف لڑھک رہی تھی۔ کسریٰ کی حکومت ایشیا کے کم و بیش نصف علاقوں پر قائم تھی اور فخر و تکبر کا لبادہ اوڑھے بازنطینی ریاست سے برسر پیکار تھی۔ دنیا میں اسلام سے قبل جو مذاہب آئے، ان میں یہودیت، عیسائیت اور مجوسیت بہت نمایاں تھی لیکن یہ تینوں مذہب جزیرہ نمائے عرب میں اپنی جڑیں نہ پکڑ سکے۔ یہودیت نہایت تنگ نظر مذہب ہے جو اخلاقیات، امید و رجا اور نجات کا درس دینے کے بجائے مجموعہ آلام بن کے رہ گیا ہے۔\nمجوسی بتوں کے پجاری نہیں تھے۔ وہ صرف دو دیوتاؤں اہورا مزدا اور اہرمن کی پوجا کرتے تھے۔ آگ کو پوجنے والے مجوسی اپنے کاہنوں کے زیر دست تھے۔ ان کے آتش کدوں میں انسانی عظمت جل کر راکھ ہو رہی تھی۔ سفید فام ایرانی اپنے آپ پر اتنا اتراتے تھے کہ حبشیوں اور ہندوستانیوں کو کوّے کہا کرتے تھے۔ ادھر عربوں کو اپنی فصاحت پر اتنا ناز تھا کہ وہ ایرانیوں کو عجمی، یعنی گونگا کہتے تھے۔\n[تصویر: مجوسیوں کی آتش گاہ (باکو، آذربائیجان)]\nتیسرا بڑا مذہب عیسائیت تھا جس نے سیدنا عیسیٰ علیہ السلام کو خدا بنا لیا اور عیسائیت کو تثلیث کے گورکھ دھندے میں الجھا دیا۔ یوں ایک الہامی نظام حیات تحریف و تبدل کا شکار ہو کر معدوم ہو گیا اور عیسائیت مختلف فرقوں میں بٹ گئی۔ اس وقت اہل عرب ہندوستانیوں کی طرح بتوں کے پجاری اور کاہنوں، جادو گروں، فال گیروں کے زیر بار تھے۔ اگر ہندوستانی بتوں کے استھانوں پر انسانی قربانی دیتے تھے تو اہل عرب غیرت کے نام پر یا بھوک و افلاس کے اندیشے سے اپنی بچیوں کو زندہ درگور کرتے تھے۔\n[تصویر: عیسائیوں کے باطل عقیدہ تثلیث کی علامت]","",{"v":500126,"im":["v5_p126.jpg"]}],[2197,"کفر اور شرک کی ان ظلمتوں اور سلطنتوں کے احوال سے رسول اللہ صلی اللہ علیہ وسلم بہ تمام و کمال آگاہ تھے۔ اس سلسلے میں رسول اللہ صلی اللہ علیہ وسلم نے جو حکمت عملی اختیار فرمائی وہ حسن تبلیغ ہی نہیں بلکہ اعلیٰ درجے کی سفارت کاری کی بھی درخشاں مثال ہے۔ آپ صلی اللہ علیہ وسلم نے دین حنیف کی دعوت دینے کے لیے مختلف سلطنتوں کے فرمانرواؤں سے رابطہ قائم کرنا شروع کیا اور انھیں اسلام کی صداقت و حقانیت سے روشناس کرانے کے لیے خطوط ارسال فرمائے۔ اس ضمن میں آپ صلی اللہ علیہ وسلم نے ایک تعارفی خط شاہ حبشہ نجاشی اصحمہ کو بھیجا۔ اور مکہ کے مظلوم مسلمانوں کو ہجرت حبشہ کی اجازت دیتے ہوئے فرمایا کہ وہ ایک بھلا مانس بادشاہ ہے اس کے ملک میں کسی پر ظلم نہیں ہوتا۔\nشاہ حبشہ سے خط کتابت کے ذریعے ہی سیدہ ام حبیبہ رضی اللہ عنہا سے آپ صلی اللہ علیہ وسلم کے نکاح کا معاملہ طے پایا۔ اللہ کے دین کا پیغام پہنچانے کے لیے آپ صلی اللہ علیہ وسلم نے سیدنا دحیہ کلبی رضی اللہ عنہ کے ذریعے ایک مکتوب گرامی بازنطینی سلطنت کے فرمانروا ہرقل کو بھی روانہ فرمایا۔ ہرقل کا دل آپ کے خط کی تاثیر سے متاثر ہوئے بغیر نہ رہ سکا لیکن وہ بودا آدمی تھا علی الاعلان قبول اسلام کی ہمت نہ کر سکا۔ بحالت جہالت ہی مر گیا۔ آپ صلی اللہ علیہ وسلم نے بازنطینی سلطنت کی باجگزار ریاستوں کے سربراہوں کو بھی مکاتیب گرامی بھیجے۔\n[تصویر: نجاشی کے نام رسول اللہ صلی اللہ علیہ وسلم کے خط کا عکس]\n[تصویر: عظیم الروم (ہرقل) کے نام رسول اللہ صلی اللہ علیہ وسلم کے خط کا عکس]","",{"v":500127,"im":["v5_p127.jpg"]}],[2198,"ایک مکتوب گرامی فرمانروائے مصر مقوقس کو بھی ارسال فرمایا۔ یہ مکتوب گرامی حاطب بن ابی بلتعہ رضی اللہ عنہ لے کر گئے تھے۔ آپ صلی اللہ علیہ وسلم نے والی دمشق حارث بن ابی شمر غسانی کو سیدنا شجاع بن وہب الاسدی رضی اللہ عنہ کے ذریعے اور والی یمامہ ہوذہ بن علی کو ایک مکتوب سلیط بن عمرو بن عبد شمس عامری رضی اللہ عنہ کے ہاتھ روانہ فرمایا اور ان امرائے کبار کو اسلام قبول کرنے کی دعوت دی۔ ایک نامہ مبارک سیدنا عبداللہ بن حذافہ سہمی رضی اللہ عنہ کے ذریعے ساسانی حاکم کے نام بھی بھیجا۔ سلطنت فارس کے فرمانروا خسرو پرویز کو بھی آپ نے ایک مکتوب ارسال فرمایا اور اسے اسلام قبول کرنے کی دعوت دی۔ اس بدبخت نے آپ صلی اللہ علیہ وسلم کا نامہ گرامی پھاڑ دیا۔ اس گستاخی کی سزا اسے یہ ملی کہ اس کے بیٹے شیرویہ نے اسے قتل کر ڈالا۔\n[تصویر: مقوقس کے نام رسول اللہ صلی اللہ علیہ وسلم کے خط کا عکس]\n[تصویر: حارث بن ابی شمر غسانی کے نام رسول اللہ صلی اللہ علیہ وسلم کے خط کا عکس]\nنبی اکرم صلی اللہ علیہ وسلم نے والی بحرین منذر بن ساوی کو سیدنا علاء بن حضرمی رضی اللہ عنہ کے ذریعے اور والیان عمان ابنائے جلندی جیفر اور عبد کی طرف سیدنا عمرو بن العاص رضی اللہ عنہ کی معرفت مکاتیب ارسال فرمائے۔ جیفر اور عبد نے سیدنا عمرو بن العاص رضی اللہ عنہ کے ہاتھ پر اسلام قبول کر لیا۔ رسالت مآب صلی اللہ علیہ وسلم نے دین اسلام کے فروغ کے لیے مکاتیب کے ساتھ ساتھ متعدد بادشاہوں کو گرانقدر تحائف بھی مرحمت فرمائے۔ جواباً ان کی طرف سے بھی آپ صلی اللہ علیہ وسلم کی خدمت میں تحائف بھیجے گئے۔ آپ صلی اللہ علیہ وسلم کی بالغ نظری اور اسلام کے ابلاغ و نفاذ کے لیے آپ صلی اللہ علیہ وسلم کی تڑپ اور طلب کو اللہ تعالیٰ نے قبولیت سے نوازا۔ یوں نہ صرف پورے جزیرہ عرب میں اسلام کا اجالا پھیلا بلکہ آفتاب اسلام کی شعاعیں عرب کے باہر دور دراز کے\n[تصویر: منذر بن ساوی کے نام رسول اللہ صلی اللہ علیہ وسلم کے خط کا عکس]","",{"v":500128,"im":["v5_p128.jpg"]}],[2199,"خطوں پر بھی پڑنے لگیں۔\nنبی صلی اللہ علیہ وسلم مدینہ پہنچے تو سب سے پہلے امور داخلہ پر توجہ دی۔ انصار و مہاجرین میں مؤاخات قائم کی۔ پھر مدینہ کے باشندوں سے جن میں انصار و مہاجرین کے علاوہ مشرکین عرب اور یہود و نصاریٰ بھی شامل تھے، ’’میثاق مدینہ‘‘ طے پایا۔\n§امن و امان اور ایفائے عہد\nاسلامی ریاست جس نازک اور مشکل دور سے گزر رہی تھی، اس کے لیے ضروری تھا کہ سب سے پہلے عدل و انصاف کے قیام اور امن و امان کے استحکام کا اہتمام کیا جائے۔ امن و امان کی پہلی شرط ہی صلح اور دوستی ہے، چنانچہ نبی صلی اللہ علیہ وسلم نے سب سے پہلا معاہدہ اہل مدینہ سے کیا۔ اس کے بعد قریبی قبائل سے معاہدے کیے۔ آپ صلی اللہ علیہ وسلم جب کسی سے معاہدہ کرتے تو اس کی پوری پابندی فرماتے تھے۔ آپ کے بدترین دشمنوں کو بھی آپ صلی اللہ علیہ وسلم سے کبھی بدعہدی اور بے وفائی کی شکایت نہیں ہوئی۔\nدور نبوی میں معاہدوں کی مختلف نوعیتیں تھیں جن کے شواہد و شرائط مختلف ادوار میں طے پانے والے معاہدوں میں دیکھے جا سکتے ہیں۔\nمدینہ کے داخلی استحکام کا بندوبست کر کے نبی صلی اللہ علیہ وسلم نے اردگرد کے قبائل کی سازشوں اور شرارتوں کا سد باب کیا اور ان کی عصبیتوں کو نہایت حکیمانہ سیاسی تدبر سے رفع کیا۔ امن و استحکام کی خاطر ودان تک کا سفر فرمایا۔ آپ نے اس سفر میں قبیلہ بنو ضمرہ بن بکر بن عبد مناة سے معاہدہ کیا۔ اس معاہدے پر مخشی بن عمرو الضمری نے دستخط کیے۔ اس وقت یہ قبیلہ بنو ضمرہ کے سردار تھے۔(1)\nقبیلہ بنو ضمرہ سے معاہدہ کرنے کے بعد نبی صلی اللہ علیہ وسلم نے ربیع الاول 2ھ میں رضویٰ (نواح ینبع) کی جانب سفر فرمایا\n[تصویر: جبل رضویٰ]","",{"v":500129,"fn":"(1) السيرة لابن هشام: 591/2","im":["v5_p129.jpg"]}],[2200,"اور کوہ بواط کے لوگوں سے معاہدہ کر لیا۔ اسی سال جمادی الآخرہ میں ذی العشیرہ گئے اور بنو مدلج سے معاہدہ فرمایا۔(1)\n§معاہدوں کا اسلوب\nرسول اللہ صلی اللہ علیہ وسلم امن اور آشتی کے پیغامبر تھے۔ آپ تلوار چلانے نہیں آئے تھے بلکہ دنیا میں حق و صداقت کا نور پھیلانے اور صلح و امن قائم کرنے کے لیے تشریف لائے تھے۔ جن قبائل کے ساتھ معاہدے ہوئے، ان کا تذکرہ اپنی اپنی جگہ پر آئے گا۔ اس ضمن میں معاہدہ جہینہ، معاہدہ حدیبیہ، معاہدہ ثقیف، معاہدہ دومۃ الجندل، معاہدہ متقنا اور معاہدہ نجران کی مثالیں کافی ہیں۔\n[تصویر: وادی بواط]\nدور نبوت میں رسول اللہ صلی اللہ علیہ وسلم نے جو معاہدے فرمائے، ان کا اسلوب مبارک یہ تھا کہ ہر معاہدے کا آغاز بسم اللہ سے ہوتا تھا، پھر سب سے پہلے فریقین کے نمائندوں کے نام مع خطابات درج ہوتے تھے۔ معاہدہ حدیبیہ کے سوا نبی اکرم صلی اللہ علیہ وسلم نے جتنے معاہدے کیے، ان سب کے متن میں آپ کے اسم گرامی ’’محمد‘‘ کے معاً بعد رسول اللہ (صلی اللہ علیہ وسلم) بھی درج ہوتا تھا۔ معاہدے کے آخر میں گواہوں کا اندراج کیا جاتا تھا۔ معاہدے کے مندرجات مقاصد کی بنا پر ہوتے تھے، مثلاً: مذہبی، سیاسی یا اقتصادی اغراض کا تذکرہ کیا جاتا تھا۔ معاہدے کی شقیں سادہ اور متوازن ہوتیں۔ تفصیلات لکھنے پر زیادہ توجہ دی جاتی اور طے شدہ شرائط کی پابندی کا خاص اہتمام کیا جاتا تھا۔\n[تصویر: قدیم و جدید ذی العشیرہ]\nرسول اللہ صلی اللہ علیہ وسلم نے جتنے بھی بیرونی ملکوں کے فرمانرواؤں سے خط کتابت کی، سفارتی تبادلوں کا اہتمام کیا اور مختلف نوعیت کے جو معاہدے کیے وہ سب امور خارجہ کے زمرے میں آتے ہیں۔ امور خارجہ کے لیے آپ صلی اللہ علیہ وسلم نے","",{"v":500130,"fn":"(1) السيرة لابن هشام: 598/2","im":["v5_p130.jpg"]}],[2201,"نے خاص لیاقت و قابلیت کے ان افراد کا تقرر فرمایا جو غیر ملکی زبانوں کے ماہر اور بہترین ترجمان تھے۔ ان کا کام غیر ملکی دستاویزات و خطوط کا مطالعہ، ترجمہ، گفتگو کی صورت میں ترجمانی اور امراء و رؤساء کے نامہ و پیام کا جواب دینا تھا۔\n§معاہدوں کے تین ادوار\nمعاہدات کا پہلا دور غزوہ بدر سے پہلے کا ہے۔ اس دور کے معاہدات کے پس منظر میں قریش مکہ کا اعلان جنگ کارفرما تھا، اس لیے جن قبائل کے ساتھ دوستی، حلف یا ان کی غیر جانب داری سے مدینہ کی نوزائیدہ مملکت کو فائدہ پہنچ سکتا تھا، ان کے ساتھ معاہدے طے پائے۔ قریش مکہ کی سیاسی اور اقتصادی برتری کی وجہ سے اس طرح کے معاہدے زیادہ تعداد میں نہ ہو سکے، البتہ جو تین معاہدے اس دور میں طے پائے، وہ اس عہد میں مملکت مدینہ کی کمزور عسکری حالت کے پیش نظر بہت سود مند ثابت ہوئے۔\nدوسرے دور کا واحد، مگر اہم معاہدہ صلح حدیبیہ ہے۔ اس معاہدے کے اثرات بڑے دور رس تھے۔ سیرت نبوی کا یہ واقعہ زبردست اہمیت کا حامل ہے۔ فقہاء نے اس معاہدے کی شقوں سے امور خارجہ سے متعلقہ نہایت اہم اصول بھی وضع کیے ہیں۔\nمعاہدات عہد نبوی کا تیسرا دور صلح حدیبیہ سے لے کر فتح مکہ تک کا ہے۔ اب وہ زمانہ شروع ہوتا ہے جب یہ معاہدے، معاہدوں سے کہیں زیادہ ’’امان ناموں‘‘ کا درجہ اختیار کر گئے۔ یہ معاہدے ان مختلف مراعات پر مبنی تھے جو رسول اللہ صلی اللہ علیہ وسلم مفتوح قبائل کو از خود عطا فرماتے تھے جیسا کہ وادی خیبر کی شکست خوردہ یہودی آبادی کے معاہدے سے عیاں ہے۔ اگر آپ صلی اللہ علیہ وسلم ان مفتوح یہودیوں کو غلام بنا لیتے یا قتل کر دیتے یا ملک بدر کر دیتے تو آپ صلی اللہ علیہ وسلم کا یہ عمل مبنی بر انصاف اس دور کے رواج اور خود شریعت موسوی کے عین مطابق ہوتا۔ لیکن رحمت عالم صلی اللہ علیہ وسلم نے ایسا نہیں کیا۔ معاہدہ کرنے ہی کو ترجیح دی۔\nفتح مکہ کے بعد تقریباً پورا عرب اسلامی مملکت میں شامل ہو چکا تھا۔ جو قبائل اسلام قبول کرتے تھے، ان کے ساتھ کسی طرح کے معاہدے کا سوال ہی پیدا نہیں ہوتا تھا۔ البتہ قبائل کے وہ افراد جو اپنے مذہب پر قائم اور خارج از اسلام رہنا چاہتے تھے، انھیں جزیے کے عوض امان عطا کی جاتی تھی۔ اس دور کے عہد ناموں کو معاہدات کی فہرست میں اس لیے شامل کیا جاتا ہے کہ ان ’’امان ناموں‘‘ میں ان مراعات کا ذکر ہے جو حضور صلی اللہ علیہ وسلم نے ذمیوں کو عطا فرمائی تھیں۔(1)","",{"v":500131,"fn":"(1) سيرة خير الأنام، ص: 348"}],[2202,"§معاہدوں کی پابندی کا حکم\nشریعت اسلامی نے معاہدوں کی پاسداری کا حکم دیا ہے اور اس پر اجر عظیم کا وعدہ فرمایا ہے۔ فرمان الہی ہے: ﴿وَمَنْ أَوْفَىٰ بِمَا عَاهَدَ عَلَيْهُ اللَّهَ فَسَيُؤْتِيهِ أَجْرًا عَظِيمًا ۝﴾(1) ’’اور جس نے (وہ) عہد پورا کیا جو اس نے اللہ سے باندھا تھا تو عنقریب وہ اسے بہت بڑا اجر دے گا۔‘‘\nدوسری جانب اللہ تعالیٰ نے نبی صلی اللہ علیہ وسلم کو معاہدوں کی خلاف ورزی کرنے والوں سے جنگ کا حکم دیا، ارشاد فرمایا: ﴿الَّذِينَ عَاهَدْتَ مِنْهُمْ ثُمَّ يَنْقُضُونَ عَهْدَهُمْ فِي كُلِّ مَرَّةٍ وَهُمْ لَا يَتَّقُونَ ۝ فَإِمَّا تَثْقَفَنَّهُمْ فِي الْحَرْبِ فَشَرِّدْ بِهِمْ مَنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ ۝﴾ ’’وہ لوگ جن سے آپ نے معاہدہ کیا، پھر وہ ہر بار اپنا عہد توڑ ڈالتے ہیں اور وہ (اللہ سے ذرا) نہیں ڈرتے۔ پھر اگر آپ ان کو لڑائی میں پائیں تو ان کے ساتھ ان لوگوں کو بھی بھگا دیں جو ان کے پیچھے ہوں، شاید وہ نصیحت پکڑیں۔‘‘(2)","",{"v":500132,"fn":"(1) الفتح 48:10\n(2) الأنفال 8:56,57"}],[2203,"§ریاست کا دفاع\nاسلام کے عائد کردہ واجبات و فرائض میں انتہائی اہم بلکہ اکثر حالتوں میں ایمان و کفر تک کا فیصلہ کر دینے والا فرض دفاع ہے۔ اگر کسی مسلمان حکومت یا مسلمان آبادی پر کوئی غیر مسلم گروہ حملہ کرے تو دنیا بھر کے مسلمانوں پر شرعاً فرض ہو جاتا ہے کہ وہ مظلوم مسلمانوں کے دفاع کے لیے اٹھ کھڑے ہوں اور اس حکومت اور آبادی کو غیر مسلم قوت کے قبضے سے بچائیں۔ اگر قبضہ ہو گیا ہو تو اس سے نجات دلائیں اور اس کام کے لیے اپنی ساری قوتیں اور کوششیں وقف کریں، چنانچہ جب کفار مکہ اور مشرک قبائل کے حملے کے خطرات بڑھے تو نبی صلی اللہ علیہ وسلم نے ایک مضبوط عسکری تنظیم کی تیاری پر بھرپور توجہ دی۔\nنبی صلی اللہ علیہ وسلم نے مدینہ کے تحفظ کے لیے تحریری عہد و پیمان ہی پر اکتفا نہیں فرمایا بلکہ حرب و ضرب کے وہ تمام طریقے اختیار فرمائے جو اس زمانے میں مروج تھے، چنانچہ آپ نے ایک نہایت مضبوط دفاعی نظام قائم کیا۔ مسلمانوں کو جنگ لڑنے کے جو طریقے آتے تھے، آپ صلی اللہ علیہ وسلم نے انھیں زیادہ کارگر، موثر اور ترقی یافتہ بناتے رہنے کی ضرورت کو ایک مستقل اصول بنا دیا۔ رسول اللہ صلی اللہ علیہ وسلم اہل باطل کے ارادوں اور ان کی نقل و حرکت پر کڑی نظر رکھتے تھے اور ان کی حربی سرگرمیوں اور اسلحہ سازی کے جدید تر رجحانات سے باخبر رہتے تھے۔ اس سلسلے میں آپ صلی اللہ علیہ وسلم خفیہ سراغ رسانی کے طریقے بھی بروئے کار لاتے رہے اور دشمنان اسلام کے ناپاک عزائم سے آگہی کے لیے مختلف صحابہ کرام رضی اللہ عنہم کو مطلوبہ معلومات کی غرض سے مختلف مقامات پر روانہ فرماتے رہے۔\n[تصویر: منجنیق کا خاکہ]\nمجاہدین اسلام کو تیر اندازی، تیغ زنی اور نیزوں کی لڑائی میں تو خوب مہارت تھی مگر وہ قلعہ شکن آلات سے نا آشنا تھے۔ رسول اللہ صلی اللہ علیہ وسلم کو معلوم ہوا کہ علاقہ جرش میں منجنیق، دبابہ (قلعہ شکن مشین، ٹینک) اور دوسرے حربی آلات","",{"v":500133,"im":["v5_p133.jpg"]}],[2204,"[تصویر: جرش کے کھنڈر]\nتیار کیے جاتے ہیں تو آپ صلی اللہ علیہ وسلم نے عروہ بن مسعود ثقفی، غیلان بن سلمہ ثقفی اور چند دیگر تجربہ کار صحابہ کرام رضی اللہ عنہم کو جدید اسلحہ سازی سیکھنے کے لیے فوراً جرش روانہ کر دیا۔ اس طرح آپ نے مسلمانوں کو ہمیشہ کے لیے خبردار کر دیا کہ وہ قیامت تک باطل کے نشانے پر ہیں۔ اس لیے انھیں ہر آن ہر گھڑی چوکس اور باطل کے جدید ترین حربی آلات و اسلحہ اور تکنیک سے نہ صرف آگاہ رہنا چاہیے بلکہ اس میں مہارت حاصل کرنے کے ساتھ ساتھ مسلسل ترقی کرتے رہنا چاہیے۔\n§نبی صلی اللہ علیہ وسلم کی عسکری تیاریوں کا طریق کار\nاگرچہ مسلمان ثابت قدم تھے اور ان کا ایمان غیر متزلزل تھا، پھر بھی نبی صلی اللہ علیہ وسلم نے تمام دستیاب اسباب و وسائل سے کام لیا اور کفار کی شرانگیزیوں کے سدباب کے لیے منصوبہ بندی فرمانے لگے، چنانچہ اسلامی ریاست کے استحکام کے لیے آپ نے مضبوط عسکری تنظیم اور جری فوج منظم کرنے کی تیاری شروع فرما دی۔ ریاست میں ذوق حرب و ضرب، فوجی صلاحیتوں، قائدانہ خوبیوں، عسکری تجربے، جسمانی قوت، روحانی بلندی اور مادی وسائل کی کوئی کمی نہیں تھی۔ آپ نے بتدریج اس پورے اثاثے کو مرتب اور منظم کر دیا، تاہم اسلامی سلطنت کی عسکری تنظیم میں خاصا وقت لگا۔ بعد ازاں اسی قوت و صلاحیت کی بدولت مجاہدین اسلام تیزی سے ارتقائی مراحل طے کرتے اور جزیرہ نمائے عرب کے طول و عرض میں اسلام کی اشاعت کے جھنڈے گاڑتے چلے گئے۔","",{"v":500134,"im":["v5_p134.jpg"]}],[2205,"§جہاد کا اصل مقصد\nاسلام میں جنگ کا مقصد انتقام لینا، دوسرے ملکوں پر قبضہ کرنا یا مال و منال حاصل کرنا نہیں، نہ مجاہدین اسلام کو حکمرانی کی ہوس ہوتی ہے، اس کے برعکس اسلام نے جنگ میں اخلاقی حدود کا پاس کرنے اور ظلم و ستم کے تمام ہتھکنڈوں کو ختم کرنے کے لیے جہاد فی سبیل اللہ کا درس دیا ہے۔ جب ظلم و ستم حد سے تجاوز کر جائے اور معاشرتی، اخلاقی اور سفارتی چارہ جوئیاں ناکام ہو جائیں تو پھر جہاد ہی وہ سبیل ہے جس کے ذریعے سے ظلم و ستم کی بیخ کنی اور اللہ کی بڑائی کی صدائیں بلند ہوتی ہیں۔ جہاد فی سبیل اللہ کے اصل معنی ہی دین اسلام کے دفاع اور اعلائے کلمۃ اللہ کے لیے انتہائی کوشش کرنا ہے۔ اس مقدس راستے کا انتہائی قدم اللہ کے لیے اپنے نفس کو قربان کرنا ہے۔\n§صلح جوئی\nنبی صلی اللہ علیہ وسلم کی بعثت کا اصل مقصد صرف اللہ کے دین کا نفاذ تھا۔ جنگ انتہائی ناگزیر مجبوری کی حالت میں ہوتی تھی اور معرکہ آرائی کا انتہائی قدم اس وقت اٹھایا جاتا تھا جب کفار اپنے مکروہ اور معاندانہ عزائم سے باز نہ آتے۔ آپ صلی اللہ علیہ وسلم ہر طرح کوشش فرماتے کہ کسی طرح جنگ ٹل جائے۔ اسی لیے آپ صلی اللہ علیہ وسلم اور آپ کے جاں نثار صحابہ عین میدان جنگ میں بھی صلح کی شرائط پیش فرما دیتے تھے تا کہ جنگ بند کر دی جائے۔ عین لڑائی کے دوران بھی اگر کوئی صلح کی درخواست کرتا تو آپ صلی اللہ علیہ وسلم اسے قبول فرما لیتے تھے۔ اسی معمول مبارک کی بنا پر آپ صلی اللہ علیہ وسلم نے بعض لوگوں سے جنگ سے پہلے ہی صلح کر لی اور بعض قبائل سے معاہدے بھی کیے۔\n§مشروع اور غیر مشروع جنگ\nجہاد کے اصلی منشا کے برعکس جہاں کہیں بھی جنگ ہوگی، وہ فساد پر منتج ہوگی۔ ابن خلدون کہتے ہیں: جنگ کی مشروعیت دو طرح کی ہے اور غیر مشروع جنگ بھی دو قسموں پر مشتمل ہے۔ جنگ ابتدا ہی سے وقوع پذیر رہی ہے چونکہ یہ ایک فطری اور بشری معاملہ ہے، اس لیے کوئی امت کسی بھی مرحلے میں جنگ سے الگ نہیں رہ سکتی۔ جنگ کی چار قسمیں ہیں:\n1 ایک جنگ غیرت اور حمیت کی بنا پر ہوتی ہے۔ یہ عموماً قبائل اور خاندانوں کی رقابت کی بنا پر چھڑتی ہے۔\n2 دشمنی کی بنا پر وحشی قوموں کے مابین جنگ برپا ہوتی ہے، جیسے جاہلیت میں عرب، ترکمان، کرد اور تاتاری وغیرہ باہم لڑتے رہتے تھے۔ ان کی معیشت کا انحصار ہی جنگ و جدل پر تھا۔","",{"v":500135}],[2206,"3 صرف اللہ کے لیے اور دینی اغراض و مقاصد کے لیے لڑائی کو جہاد فی سبیل اللہ کہا جاتا ہے۔\n4 بادشاہ غضب میں آکر دوسری مملکتوں کے خلاف جنگ کرتے ہیں یا جو باغی ہوتے ہیں، ان کے خلاف لڑتے ہیں۔\nاسلام نے غیرت، مقابلہ آرائی اور دشمنی کے سبب سے ہونے والی تمام لڑائیوں کو جرم قرار دیا ہے۔ اس کے برعکس اللہ کے لیے اور دینی حمیت کے لیے جنگ کو مشروع ٹھہرایا ہے۔ وہ جنگ جو سرکشوں کے خلاف ہو اور عدل قائم کرنے کے لیے کی جائے، اسے بھی جائز قرار دیا ہے۔(1)\nنبی صلی اللہ علیہ وسلم کی جنگی حکمت عملی ابلاغ اسلام، دفاع اسلام اور دفاع مسلمین کے لیے تھی۔ آپ کو کسی پر اقتصادی تفوق اور معاشی برتری حاصل کرنے کی کوئی تمنا نہیں تھی۔\n§جنگ کے مہذب قواعد و ضوابط\nرسول اللہ صلی اللہ علیہ وسلم سے پہلے جنگ وحشت، بہیمیت، غارتگری اور ہوس ملک گیری کا نام تھا جس کا اصل محرک انتقام، تفاخر یا مال و متاع کا حصول ہوتا تھا۔ جب جنگ کا طبل بجتا تو مقاتلین اور غیر مقاتلین کا امتیاز اٹھ جاتا تھا۔ دشمن قوم کا ہر فرد دشمن بن جاتا تھا۔ عورتوں، بچوں اور بوڑھوں غرضیکہ مخالف قوم کے ہر فرد کے ساتھ یکساں وحشیانہ برتاؤ کیا جاتا تھا۔\nنبی صلی اللہ علیہ وسلم نے جنگ کے مہذب ضابطے اور قوانین بنائے۔ اس کے آداب اور اخلاقی حدود متعین کیے۔ مقاتلین اور غیر مقاتلین میں اور معاہدین اور مسافروں میں فرق قائم کیا۔ سفراء، مفتوح قوموں اور اسیران جنگ کے لیے نہایت کریمانہ حقوق متعین کیے۔ غفلت میں حملہ، آگ لگانے، لوٹ مار، مثلہ، عورتوں، بچوں، بے ضرر بوڑھوں، غلاموں اور قیدیوں کے قتل، بدعہدی اور دیگر وحشیانہ افعال کو ممنوع قرار دیا۔ حق یہ ہے کہ اسلام کا عسکری نظام بھی رحمت و رافت کے جذبوں سے لبریز ہے۔\n§فساد انگیزی سے بچنے کا حکم\nکفار مکہ مرکز اسلام پر یلغار کے لیے تیاریوں میں مصروف تھے، لہذا نبی صلی اللہ علیہ وسلم کے لیے دفاعی تدابیر اختیار کرنا اور مسلمانوں کو جہاد پر آمادہ کرنا ضروری ہو گیا، جہاد اسلام کا وہ عظیم الشان جوہر عمل ہے جسے اللہ تعالیٰ نے دین اسلام کی حفاظت اور مسلمانوں کے تحفظ کے لیے فرض قرار دیا ہے۔ اسلام نے امن و سلامتی کا درس دیا ہے اور لڑائی جھگڑوں","",{"v":500136,"fn":"(1) مقدمہ ابن خلدون، ص: 226"}],[2207,"اور فساد سے پرہیز کی تلقین فرمائی ہے بلکہ فساد کو گناہ سے تعبیر کیا ہے۔ فرمان الہی ہے:\n﴿تِلْكَ الدَّارُ الْآخِرَةُ نَجْعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوًّا فِي الْأَرْضِ وَلَا فَسَادًا ۚ وَالْعَاقِبَةُ لِلْمُتَّقِينَ ۝﴾\n’’وہ آخرت کا گھر ہم ان لوگوں کو دیں گے جو زمین میں نہ بڑائی چاہتے ہیں اور نہ فساد اور (اچھا) انجام تو پرہیزگاروں ہی کے لیے ہے۔‘‘(1)\nاس سے یہ حقیقت ثابت ہوتی ہے کہ اللہ نے محض توسیع ریاست کے لیے جنگ کو حرام قرار دیا ہے، اس لیے کہ کسی دوسرے کی زمین ہڑپ کرنا گناہ ہے جسے اللہ نے فساد سے تعبیر کیا ہے۔ فرمان الہی ہے:\n﴿وَإِذَا تَوَلَّىٰ سَعَىٰ فِي الْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ الْحَرْثَ وَالنَّسْلَ ۗ وَاللَّهُ لَا يُحِبُّ الْفَسَادَ ۝﴾\n’’اور جب وہ (جھگڑالو شخص) پلٹتا ہے تو کوشش کرتا ہے کہ زمین میں فساد پھیلائے، کھیتوں اور نسل کو تباہ کرے اور اللہ فساد کو پسند نہیں کرتا۔‘‘(2)\n§اسلام جنگ اور جبر کا نہیں، امن و سلامتی کا دین ہے\nاسلام میں تلوار کے ذریعے کسی کو مسلمان ہونے کے لیے مجبور نہیں کیا گیا۔ فرمان الہی ہے:\n﴿لَا إِكْرَاهَ فِي الدِّينِ ۖ قَدْ تَبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ ۝﴾\n’’دین میں کوئی زبردستی نہیں۔ ہدایت، گمراہی سے واضح ہو چکی ہے۔‘‘(3)\n﴿وَلَوْ شَاءَ رَبُّكَ لَآمَنَ مَنْ فِي الْأَرْضِ كُلُّهُمْ جَمِيعًا ۚ أَفَأَنْتَ تُكْرِهُ النَّاسَ حَتَّىٰ يَكُونُوا مُؤْمِنِينَ ۝﴾\n’’اور اگر آپ کا رب چاہتا تو جو لوگ زمین میں ہیں، سب کے سب ایمان لے آتے، پھر کیا آپ لوگوں کو مجبور کریں گے حتی کہ وہ مومن ہو جائیں؟‘‘(4)\n﴿مَنْ يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ ۖ وَمَنْ يُضْلِلْ فَلَنْ تَجِدَ لَهُ وَلِيًّا مُرْشِدًا ۝﴾\n’’جسے اللہ ہدایت دے، وہی ہدایت یافتہ ہے اور جسے وہ گمراہ کر دے، اس کے لیے آپ ہرگز کوئی رہنما دوست نہیں پائیں گے۔‘‘(5)\n§دفاع کا حق\nاسلام نظری، معنوی اور عملی لحاظ سے سب کے لیے سلامتی کا ضامن ہے۔ لیکن ظلم و جبر اور تعصب و زیادتی کی","",{"v":500137,"fn":"(1) القصص 28:83\n(2) البقرۃ 2:205\n(3) البقرۃ 2:256\n(4) یونس 10:99\n(5) الکہف 18:17"}],[2208,"صورت میں دفاع کا حق بھی مرحمت فرماتا ہے۔\nقرآن مجید میں ہے:\n﴿وَقَاتِلُوا فِي سَبِيلِ اللَّهِ الَّذِينَ يُقَاتِلُونَكُمْ وَلَا تَعْتَدُوا ۚ إِنَّ اللَّهَ لَا يُحِبُّ الْمُعْتَدِينَ ۝ وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُمْ مِنْ حَيْثُ أَخْرَجُوكُمْ ۚ وَالْفِتْنَةُ أَشَدُّ مِنَ الْقَتْلِ ۗ وَلَا تُقَاتِلُوهُمْ عِنْدَ الْمَسْجِدِ الْحَرَامِ حَتَّىٰ يُقَاتِلُوكُمْ فِيهِ ۖ فَإِنْ قَاتَلُوكُمْ فَاقْتُلُوهُمْ ۗ كَذَٰلِكَ جَزَاءُ الْكَافِرِينَ ۝ فَإِنِ انْتَهَوْا فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ ۝ وَقَاتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونُ الدِّينُ لِلَّهِ ۖ فَإِنِ انْتَهَوْا فَلَا عُدْوَانَ إِلَّا عَلَى الظَّالِمِينَ ۝﴾\n’’اور تم اللہ کی راہ میں ان لوگوں سے لڑو (جہاد کرو) جو تم سے لڑتے ہیں اور تم زیادتی نہ کرو، بے شک اللہ زیادتی کرنے والوں کو پسند نہیں کرتا۔ اور تم انھیں جہاں بھی پاؤ، ان کو قتل کر دو اور تم انھیں نکال دو جہاں سے انھوں نے تمھیں نکالا اور فتنہ قتل سے زیادہ سخت (گناہ) ہے اور تم ان سے مسجد حرام کے پاس نہ لڑو یہاں تک کہ وہ اس میں تم سے لڑیں، پھر اگر وہ تم سے لڑیں تو تم انھیں قتل کرو، ایسے کافروں کی یہی سزا ہے۔ پھر اگر وہ باز آ جائیں تو بے شک اللہ بہت بخشنے والا (اور) بہت رحم کرنے والا ہے۔ اور ان سے جنگ کرو یہاں تک کہ فتنہ باقی نہ رہے اور دین صرف اللہ کے لیے ہو جائے، پھر اگر وہ باز آ جائیں تو ظالموں کے سوا کسی پر زیادتی جائز نہیں۔‘‘(1)\n§جہاد کے وسائل اور اسلحہ\nنبی صلی اللہ علیہ وسلم نے اسلامی ریاست کے دفاع میں اپنے عہد مبارک کے تمام مروجہ جدید ترین ہتھیار اور دستیاب وسائل استعمال فرمائے، مثلاً: آپ دفاعی معرکوں میں زرہوں اور ڈھالوں سے کام لینے کے علاوہ خندقوں اور دیواروں کی اوٹ بھی بروئے کار لاتے رہے۔ آپ صلی اللہ علیہ وسلم نے میدان جنگ میں مطلوب مقامات پر بچھائے جانے والے مخصوص نوکیلے آلات بھی نصب کرائے۔\nقتال کے لیے یہ اسلحہ استعمال فرمایا: تلوار، تیر، نیزہ، سنگباری کے لیے منجنیق اور دبابہ (ٹینک نما مشین جس میں قلعہ شکن ماہرین موجود ہوتے تھے)۔ نقل و حمل کے لیے آپ صلی اللہ علیہ وسلم کی سواریوں میں گھوڑے اور اونٹ زیر استعمال رہے۔","",{"v":500138,"fn":"(1) البقرۃ 2:190-193"}],[2209,"§جہاد میں شرکت کی شرائط\nاسلام میں جہاد فرض ہے لیکن اس میں بشری تقاضوں کو بھی ملحوظ رکھا گیا ہے اور مجاہدین کے لیے چند شرائط عائد کی گئی ہیں:\n1 لشکر میں شامل ہونے والا مسلمان ہو۔ غزوہ بدر کے موقع پر ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: میں آپ کے ساتھ معرکے میں شریک ہونا چاہتا ہوں۔ آپ صلی اللہ علیہ وسلم نے پوچھا: «تُؤْمِنُ بِاللَّهِ وَرَسُولِهِ؟» ’’کیا تو اللہ اور اس کے رسول پر ایمان رکھتا ہے؟‘‘ اس نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: «فَارْجِعْ فَلَنْ أَسْتَعِينَ بِمُشْرِكٍ» ’’لوٹ جا! میں مشرک سے مدد نہیں لیتا۔‘‘\n2 وہ بالغ ہو، مثلاً: سیدنا عبد اللہ بن عمر رضی اللہ عنہما بدر کے موقع پر بالغ نہیں تھے، اس لیے انھیں شامل نہیں کیا گیا۔ احد کے سال وہ بالغ ہو گئے تھے، اس لیے احد میں شامل کر لیے گئے۔\n3 وہ تندرست و توانا ہو، یعنی نابینا یا لاغر نہ ہو، جسمانی نقائص سے مبرا ہو۔\nقرآن کریم میں ارشاد ہے:\n﴿لَيْسَ عَلَى الضُّعَفَاءِ وَلَا عَلَى الْمَرْضَىٰ وَلَا عَلَى الَّذِينَ لَا يَجِدُونَ مَا يُنْفِقُونَ حَرَجٌ إِذَا نَصَحُوا لِلَّهِ وَرَسُولِهِ ۝﴾\n’’ضعیفوں اور بیماروں پر اور جو لوگ کوئی چیز نہیں پاتے کہ وہ خرچ کریں، ان پر (پیچھے رہنے میں) کوئی گناہ نہیں جبکہ وہ اللہ اور اس کے رسول کے لیے خیر خواہی کرتے ہوں۔‘‘(1)\n§اللہ کی راہ میں نہ نکلنے پر سماجی بائیکاٹ کا حکم\nنبی صلی اللہ علیہ وسلم نے جب غزوہ تبوک کے موقع پر جہاد کے لیے نکلنے کا حکم دیا تو تین مسلمان کعب بن مالک، ہلال بن امیہ اور مرارہ بن ربیع رضی اللہ عنہم اپنے سازگار حالات کے باوجود نہیں نکلے، محض سستی کی وجہ سے پیچھے رہ گئے۔ اللہ کی راہ میں نہ نکلنے پر آپ صلی اللہ علیہ وسلم ان حضرات سے اس قدر ناراض ہوئے کہ آپ صلی اللہ علیہ وسلم نے ان کا بائیکاٹ کر دیا۔ تمام مسلمانوں حتی کہ ان کی بیویوں کو بھی ان سے قطع تعلق کا حکم دے دیا۔ یہ ایسی عبرتناک صورتحال تھی جس سے دو چار ہو کر یہ تینوں صحابی اپنے ہی معاشرے میں اجنبی بن کر رہ گئے۔ ان کے سگے رشتہ داروں نے بھی ان سے سلام دعا ترک کر دی، زمین ان پر تنگ ہو گئی۔ یہ حضرات شدید غم اور اضطراب کی حالت میں بھی نماز پڑھنے کے لیے مسجد میں جاتے تھے اور رحمت عالم صلی اللہ علیہ وسلم کی طرف دزدیدہ نگاہوں سے دیکھتے رہتے تھے کہ شاید اب آپ صلی اللہ علیہ وسلم ان کی غفلت کا قصور معاف کر دیں لیکن اس حالت پر پورے 50 دن بیت گئے۔ یہ حضرات اللہ تعالیٰ کے حضور شام و سحر","",{"v":500139,"fn":"(1) التوبۃ 9:91"}],[2210,"روتے رہے، بخشش کی دعائیں مانگتے رہے۔ اپنی لمحاتی غفلت پر توبہ کرتے رہے۔ بالآخر اللہ تعالیٰ نے ان کی توبہ قبول فرمائی تب جا کر ان کا سماجی بائیکاٹ ختم ہوا۔\nاللہ اللہ! یہ تینوں صحابی رضی اللہ عنہم بھی نہ تم بڑے بلند پایہ حضرات تھے۔ ہمیشہ اللہ کی راہ میں نکلتے رہے۔ بس ایک دفعہ غفلت ہو گئی تو زمین ان پر تنگ کر دی گئی! آہ! اندازہ کیجیے کہ اگر اللہ پاک نے ہمیں اپنی کرم گستری سے معاف نہ فرمایا تو ہمارا کیا بنے گا۔ آج دنیا بھر میں مظلوم مسلمانوں کا خون بہایا جا رہا ہے۔ ان کی لاشیں گرائی جا رہی ہیں۔ بستیاں پھونکی جا رہی ہیں مگر ہم بدستور غفلت کی انگڑائیاں لے رہے ہیں۔ اپنے مظلوم مسلمان بھائیوں کے دفاع کے لیے نکلنا تو کجا، ہماری آنکھوں میں ان کے لیے ہمدردی کا ایک آنسو بھی نہیں ہے۔\n§اسلامی لشکر کی صف بندی\nاسلامی فوج پانچ حصوں، یعنی 1 قلب یا مرکز 2 میمنہ 3 میسرہ 4 مقدمہ اور 5 عقب یا ساقہ پر مشتمل ہوتی تھی۔ ہر چند لشکر کی یہ تقسیم دور جاہلیت میں بھی موجود تھی لیکن رسول اللہ صلی اللہ علیہ وسلم نے اس میں جدید نظم و ترتیب پیدا کی، نئی روح پھونکی اور انھیں پہلے سے کہیں زیادہ مؤثر اور منظم کر کے ایک ناقابل تسخیر اکائی یا قرآن کے الفاظ میں\n[تصویر: مسجد سیدنا کعب بن مالک رضی اللہ عنہ، دوحہ، قطر]","",{"v":500140,"im":["v5_p140.jpg"]}],[2211,"’’بنیان مرصوص‘‘ بنا دیا۔(1)\nمیدان جنگ میں رسول اللہ صلی اللہ علیہ وسلم خود ہاتھ میں چھڑی لے کر صفیں درست فرماتے تھے۔(2)\nبلکہ بقول طبری فتح مکہ کے وقت تو صف آرائی کا خصوصی اہتمام ایک مخصوص افسر کے سپرد کر دیا گیا تھا جو بلحاظ عہدہ وازع کہلاتا تھا۔(3)\nمہم پر روانگی سے پہلے ہر فوج کا شہر کے باہر معائنہ (عرض) ہوتا تھا۔ کم عمر رضا کار اور سواری یا اسلحہ سے محروم یا غیر موزوں افراد واپس بھیج دیے جاتے تھے۔(4)\nجنگ بدر میں صف آرائی کے بعد جو جامع ہدایات دی گئی تھیں، وہ یہ تھیں کہ جب تک میں حکم نہ دوں، اپنی جگہ سے کوئی حرکت نہ کرے۔ تیر اندازوں کو ہدایت دی گئی کہ دشمن دور ہو تو تیر نہ چلائے جائیں تا کہ وہ ہدف تک نہ پہنچنے کی وجہ سے ضائع نہ ہونے پائیں بلکہ جب حریف نزدیک آ جائے تو اس وقت تیر مارے جائیں۔ دشمن بالکل قریب آئے تو پتھر مار کر حملہ کیا جائے، اس سے بھی قریب تر آ جائے تو نیزہ اور تلوار چلائی جائے۔(5)\nان ہدایات سے اندازہ کیا جا سکتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم اسلحہ اور دیگر سامان حرب کے محتاط استعمال کے لیے کس قدر مجوری سے کام لیتے تھے۔\n§مورال کی بلندی اور ترغیب جہاد\nجنگ سپہ سالار فوج یا امیر لشکر کے حکم سے شروع ہوتی تھی۔ اجرائے حکم کے بعد تکبیر یا دعا کے ذریعے اللہ تعالیٰ سے امداد طلب کی جاتی تھی۔(6)\nمحاذ جنگ پر مجاہدین کا مورال (Morale) بلند کرنے کا خاص اہتمام کیا جاتا تھا۔ قرآن میں رسول اللہ صلی اللہ علیہ وسلم کو ترغیب جہاد کا یوں حکم دیا گیا:\n﴿يَا أَيُّهَا النَّبِيُّ حَرِّضِ الْمُؤْمِنِينَ عَلَى الْقِتَالِ ۝﴾\n’’اے نبی! مسلمانوں کو جہاد کی ترغیب دو۔‘‘(7)\n§لشکر اسلام کی تنظیم\nلشکر میں دو قسم کے دستے ہوتے تھے۔ ایک پیادہ اور دوسرے سوار۔ جنگ بدر میں لشکر مجاہدین کے ساتھ صرف دو سوار تھے۔ معرکہ اُحد میں مستقل سوار فوج قائم ہوئی جس کے کمانڈر سیدنا زبیر بن عوام رضی اللہ عنہ تھے۔ تبوک کے محاذ پر سوار فوج کی تعداد دس ہزار تک جا پہنچی تھی۔ ان دو قسم کے دستوں کے علاوہ بعد میں زرہ پوش پلٹن کا بھی اضافہ ہو گیا۔ اُحد میں پہلی مرتبہ 100 سپاہیوں کی زرہ پوش پلٹن شامل ہوئی تھی جبکہ فتح مکہ کے موقع پر اسلامی فوج کا ہر","",{"v":500141,"fn":"(1) الصف 61:4\n(2) عہد نبوی میں ریاست کا نشو و ارتقاء، ڈاکٹر نثار احمد، ص: 435\n(3) عہد نبوی میں نظام حکمرانی، ڈاکٹر حمید اللہ، ص: 266\n(4) الطبقات لابن سعد: 2/12\n(5) عہد نبوی میں نظام حکمرانی، ڈاکٹر حمید اللہ، ص: 266\n(6) عہد نبوی میں ریاست کا نشو و ارتقاء، ڈاکٹر نثار احمد، ص: 435\n(7) الأنفال 8:65"}],[2212,"سپاہی آہن پوش تھا۔(1)\nمیدان جنگ میں سپہ سالار فوج کا ہیڈ کوارٹر محفوظ اور اونچی جگہ پر الگ بنایا جاتا تھا تا کہ وہ فوجوں کی نقل و حرکت اور محاذ جنگ کے احوال پر نظر رکھتے ہوئے ہدایات جاری کر سکے۔ غزوہ بدر میں رسول اللہ صلی اللہ علیہ وسلم کے لیے اسی نوعیت کا ’’عریش‘‘ تیار کیا گیا تھا۔(2)\n§صاحب لواء اور صاحب رایہ\nسالار فوج کی حفاظت اور پہرہ داری کے خصوصی افسر الگ الگ مقرر کیے جاتے تھے۔ دو قسم کے افسر ہوتے تھے، ایک صاحب اللواء کہلاتا تھا اور دوسرا صاحب الرایہ۔ کتانی کی وضاحت کے مطابق لواء، رایہ کے علاوہ ہوتا تھا۔ لواء بڑا جھنڈا تھا اور امیر فوج کے ہیڈ کوارٹر پر بطور علامت لہراتا تھا، جبکہ رایہ اس سے الگ جھنڈا تھا۔ رسول اللہ صلی اللہ علیہ وسلم کا جھنڈا ’’عقاب‘‘ سے موسوم تھا۔ فوج میں جوش جہاد اور حمیت و غیرت کی روح بیدار رکھنے اور اپنے آدمیوں کو دور سے پہچان لینے کے لیے لشکر میں شامل قبائل کے الگ الگ جھنڈے بھی ہوتے تھے۔ ان کا رنگ بھی جداگانہ ہوتا تھا، مثلاً: ایک موقع پر انصار کے جھنڈے کا رنگ پیلا تھا۔(3)\nمحاذ پر دوست دشمن کی تمیز، جنگی ضرورتوں اور خفیہ نقل و حرکت کے پیش نظر مسلمان فوجیوں کے لیے شعار (یا علامتی نعرہ Code Word) بھی مقرر کیا گیا تھا۔ رسول اللہ صلی اللہ علیہ وسلم\n[تصویر: میدان بدر میں رسول اللہ صلی اللہ علیہ وسلم کے لیے بنائے گئے عریش (سائبان) کی جگہ مسجد العریش]","",{"v":500142,"fn":"(1) اسلام کا نظام حکومت، غازی حامد الانصاری، ص: 509,510\n(2) السیرۃ لابن ہشام: 2/626\n(3) عہد نبوی میں ریاست کا نشو و ارتقاء، ڈاکٹر نثار احمد، ص: 436","im":["v5_p142.jpg"]}],[2213,"معرکہ کارزار میں راز داری، فوجی حکمت عملی اور عسکری تدبر کا اس حد تک اہتمام فرماتے تھے کہ آپ صلی اللہ علیہ وسلم نے ہر جنگ میں شعار کے رمزیہ خفیہ الفاظ (Code Word) تبدیل فرما دیے۔(1)\n§جنگی قیدیوں کی رہائی کے کریمانہ طریقے\nرسول اللہ صلی اللہ علیہ وسلم نے جنگی قیدیوں کے بارے میں دو طرح کے طریقے اختیار کرنے کا حکم دیا: فدیہ لے کر چھوڑ دو یا پھر احسان کرتے ہوئے رہا کر دو۔ قرآن مجید میں ہے:\n﴿فَإِذَا لَقِيتُمُ الَّذِينَ كَفَرُوا فَضَرْبَ الرِّقَابِ ۖ حَتَّىٰ إِذَا أَثْخَنْتُمُوهُمْ فَشُدُّوا الْوَثَاقَ ۖ فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً حَتَّىٰ تَضَعَ الْحَرْبُ أَوْزَارَهَا ۝﴾\n’’چنانچہ جب تم (جہاد میں) ان لوگوں سے ملو جنھوں نے کفر کیا تو (ان کی) گردنیں مارو، حتی کہ جب تم انھیں خوب قتل کر چکو تو (قیدیوں کو) بیڑیوں میں مضبوطی سے باندھ دو، پھر یا تو اس کے بعد ان پر احسان کرنا ہے یا فدیہ (تاوان) لینا ہے، حتی کہ لڑائی اپنے ہتھیار ڈال دے۔‘‘(2)\nاس آیت کریمہ کے نزول سے پہلے ہی آپ صلی اللہ علیہ وسلم نے غزوہ بدر میں مشورے کے دوران سیدنا ابو بکر رضی اللہ عنہ کی یہ رائے پسند فرمائی تھی کہ قیدیوں سے فدیہ قبول کر کے انھیں رہا کر دیا جائے اور جس پڑھے لکھے قیدی کے پاس زر فدیہ نہیں، وہ مسلمانوں کے دس بچوں کو لکھنا پڑھنا سکھا دے اور پروانہ آزادی حاصل کر لے۔ جنگی قیدیوں پر احسان کرنے کے لیے قرآن نے ایک اور مقام پر یہ حکم دیا ہے:\n﴿وَيُطْعِمُونَ الطَّعَامَ عَلَىٰ حُبِّهِ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا ۝﴾\n’’اور وہ کھانا، اس کی محبت کے باوجود، مسکینوں اور یتیموں اور قیدیوں کو کھلاتے ہیں۔‘‘(3)\nنبی صلی اللہ علیہ وسلم نے فرمایا:\n﴿اسْتَوْصُوا بِالْأُسَارَىٰ خَيْرًا﴾\n’’قیدیوں کے سلسلے میں خیر خواہی کی وصیت قبول کرو۔‘‘(4)\n§امان طلبی کا معاملہ\nاسلامی ریاست میں کسی شخص نے کسی مسلمان سے امان طلب کی اور اس نے اسے امان دے دی تو آپ صلی اللہ علیہ وسلم","",{"v":500143,"fn":"(1) السیرۃ لابن ہشام: 2/634\n(2) محمد 47:4\n(3) الدہر 76:8\n(4) المعجم الکبیر للطبرانی: 22/393 و 977، یہ روایت ضعیف ہے۔"}],[2214,"نے یہ معاملہ قبول فرمایا۔ قرآن مجید میں ارشاد ہے:\n﴿وَإِنْ أَحَدٌ مِنَ الْمُشْرِكِينَ اسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَامَ اللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَا يَعْلَمُونَ ۝﴾\n’’اور (اے نبی!) اگر مشرکوں میں سے کوئی آپ سے پناہ مانگے تو اس کو پناہ دیں یہاں تک کہ وہ اللہ کا کلام سن لے، پھر اسے اس کی امن کی جگہ پہنچا دیں، اس لیے کہ بے شک وہ ایسے لوگ ہیں جو علم نہیں رکھتے۔‘‘(1)\nنبی صلی اللہ علیہ وسلم نے بھی یہی حکم دیا ہے:\n﴿الْمُؤْمِنُونَ تَتَكَافَأُ دِمَاؤُهُمْ وَيَسْعَىٰ بِذِمَّتِهِمْ أَدْنَاهُمْ وَهُمْ يَدٌ عَلَىٰ مَنْ سِوَاهُمْ﴾\n’’سب مومنوں کے خون آپس میں برابر ہیں۔ ان کا ادنی آدمی بھی کسی کو پناہ دے تو اس کا پورا کرنا سب پر ضروری ہے اور مسلمان دوسروں کے مقابلے میں ایک جماعت ہیں۔‘‘(2)\nاسی طرح فرمایا:\n﴿يَا أُمَّ هَانِئِ! قَدْ أَجَرْنَا مَنْ أَجَرْتِ وَأَمَّنَّا مَنْ أَمَّنْتِ﴾\n’’اے ام ہانی! جسے تو نے پناہ دی، اسے ہم نے پناہ دی، جسے تو نے امان دی، اسے ہم نے امان دی۔‘‘(3)\nریاست مدینہ کے قیام کے باوجود ام ہانی رضی اللہ عنہا نے دو قیدیوں کو امان دی تو آپ صلی اللہ علیہ وسلم نے یہ امان برقرار رکھی۔\n§بیرونی مسلمانوں سے تعلقات\nبعض ایسے مسلمان بھی تھے جن کے اہل کفر سے تعلقات تھے۔ انھوں نے مدینہ کی جانب ہجرت نہیں کی تھی اور فتح مکہ سے پہلے وہ ریاست مدینہ کے باشندے نہیں تھے۔ ان کے ساتھ تعلق کی نوعیت مدینہ کے مسلمان باشندوں سے مختلف تھی۔ ان کے ساتھ مذہبی اخوت ضرور تھی لیکن انھیں اسلامی ریاست کے قومی حقوق حاصل نہیں تھے۔ کیونکہ اسلامی ریاست کے نزدیک وہ اس کے دائرہ ذمہ داری میں شامل نہیں تھے۔ قرآن مجید نے اس بارے میں رہنمائی فرمائی ہے:","",{"v":500144,"fn":"(1) التوبۃ 9:6\n(2) مسند احمد: 1/119، سنن ابی داود: 2751\n(3) مسند احمد: 6/343، سنن ابی داود: 2763، السلسلۃ الصحیحۃ: 5/77، واللفظ لہ"}],[2215,"﴿إِنَّ الَّذِينَ آمَنُوا وَهَاجَرُوا وَجَاهَدُوا بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ فِي سَبِيلِ اللَّهِ وَالَّذِينَ آوَوْا وَنَصَرُوا أُولَٰئِكَ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ ۚ وَالَّذِينَ آمَنُوا وَلَمْ يُهَاجِرُوا مَا لَكُمْ مِنْ وَلَايَتِهِمْ مِنْ شَيْءٍ حَتَّىٰ يُهَاجِرُوا ۖ وَإِنِ اسْتَنْصَرُوكُمْ فِي الدِّينِ فَعَلَيْكُمُ النَّصْرُ إِلَّا عَلَىٰ قَوْمٍ بَيْنَكُمْ وَبَيْنَهُمْ مِيثَاقٌ ۗ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ ۝﴾\n’’بے شک جو لوگ ایمان لائے اور انھوں نے ہجرت کی اور اپنے مالوں اور اپنی جانوں کے ساتھ اللہ کی راہ میں جہاد کیا اور جنھوں نے (مہاجروں کو) اپنے ہاں جگہ دی اور (ان کی) مدد کی، وہ ایک دوسرے کے دوست ہیں۔ اور جو لوگ ایمان تو لے آئے مگر انھوں نے ہجرت نہیں کی، ان کی دوستی سے تمھیں کوئی غرض نہیں حتی کہ وہ ہجرت کریں۔ اور اگر وہ تم سے دین (کے معاملے) میں مدد مانگیں تو تم پر مدد لازم ہے مگر اس قوم کے خلاف مدد نہیں جن کا تمھارے ساتھ کوئی معاہدہ ہو۔ اور تم جو کام کرتے ہو، اللہ (اسے) خوب دیکھ رہا ہے۔‘‘(1)\nاس سلسلے میں رسول اللہ صلی اللہ علیہ وسلم نے بھی صراحت فرما دی ہے:\n﴿أَنَا بَرِيءٌ مِنْ كُلِّ مُسْلِمٍ يُقِيمُ بَيْنَ أَظْهُرِ الْمُشْرِكِينَ﴾\n’’میں کسی ایسے مسلمان کی حمایت و حفاظت کا ذمہ دار نہیں جو مشرکین کے درمیان رہتا ہو۔‘‘(2)\nاس طرح اسلامی قانون نے اس جھگڑے کی جڑ ہی کاٹ دی جو بالعموم اس وقت پیدا ہوتا ہے جب کوئی حکومت اقلیتوں کا ذمہ اپنے سر لیتی ہے تو اس کی وجہ سے ایسی الجھنیں پڑ جاتی ہیں جنھیں بار بار کی لڑائیاں بھی سلجھا نہیں سکتیں۔ فی الجملہ ایک طرف تو اسلامی ریاست نے کسی مسلمان کی طرف سے کسی کافر کو دی جانے والی امان برقرار رکھی ہے اور دوسری طرف اسلامی ریاست نے اپنی حدود کے باہر بسنے والے مسلمانوں کی ذمہ داری لینے سے احتراز کیا ہے تا کہ جنگ اور فتنہ کا کوئی امکان پیدا نہ ہو۔\n§مظلوم مسلم اقلیت کی مدد\nاسلام نے دینی اخوت کو ایک ناقابل شکست اور دائمی رشتہ قرار دیا ہے۔ چنانچہ اگر کسی جگہ مسلمانوں پر ظلم ہو رہا ہو اور وہ اسلامی ریاست سے مدد مانگیں تو مسلمانوں پر فرض ہے کہ بین الاقوامی قوانین اور اخلاقی حدود کے دائرہ کار میں رہ کر اپنے بھائیوں کی مدد کریں۔ اس سلسلے میں متعلقہ حکومتوں کے قوانین اسی وقت ترجیحی طور پر پاسداری","",{"v":500145,"fn":"(1) الأنفال 8:72\n(2) سنن ابی داود: 2645، جامع الترمذی: 1604"}],[2216,"کے مستحق ٹھہریں گے جب اسلامی ریاست کے ان ملکوں کے ساتھ امن کے معاہدے ہوں جہاں مسلمان اقلیتی شہریوں کی حیثیت سے رہتے ہوں۔ مندرجہ بالا آیت میں ﴿بَيْنَكُمْ وَبَيْنَهُمْ مِيثَاقٌ﴾ کے الفاظ سے واضح ہوتا ہے کہ اسلامی ریاست کے دوسری ریاست سے تعلقات صرف حکمرانوں تک محدود نہیں بلکہ یہ وسیع تر معنوں میں واضح طور پر دو قوموں کے باہمی تعلقات ہیں، چنانچہ اس دائرے میں رہ کر اسلامی حکومت اقلیتی مسلمانوں کے تحفظ کے اقدامات کر سکتی ہے۔ ایسے اقدامات حتی المقدور ہوتے رہنے چاہیں۔ اگر انفرادی اور اجتماعی سطح پر ایسے اقدامات نہیں کیے جائیں گے تو تمام مسلمان اللہ کے نزدیک غفلت اور بے حسی کے مجرم ٹھہریں گے۔","",{"v":500146}],[2217,"باب 2\n§یہود مدینہ کا کردار\nیہود مدینہ نے خاتم الانبیاء کی ذات بابرکات سے فیضیاب ہونے اور راہ حق پانے کا نادر موقع گنوا دیا اور اپنی پست فطرت کے چہرے سے سارے نقاب الٹ دیے۔ قرآن کریم کی روشنی میں ان لوگوں کے خدو خال ملاحظہ فرمائیے۔","",{"v":500147}],[2218,"﴿وَاذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ وَمِيثَاقَهُ الَّذِي وَاثَقَكُمْ بِهِ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا ۝﴾\n’’اور تم پر جو اللہ کی نعمت ہوئی اسے یاد رکھو، اور وہ عہد بھی یاد رکھو جو تم نے اس کے ساتھ باندھا، جب تم نے کہا کہ ہم نے سنا اور اطاعت کی۔‘‘ (المائدۃ 5:7)","",{"v":500148}],[2219,"§اس باب میں\nآپ کو یہودیوں کے کرتوتوں کی حیرت انگیز تفصیلات ملیں گی۔ ’’یہودا‘‘ عبرانی زبان کا لفظ ہے۔ اس کا مطلب ہے ’’جس کی تعریف کی گئی‘‘۔ لیکن یہودی اس نسبت کے باوجود اپنی پوری تاریخ میں کبھی اس تعریف کے مستحق نہیں ٹھہرے۔\nمدینہ منورہ میں ان کے تین قبیلے بنو قینقاع، بنو نضیر اور بنو قریظہ آباد تھے۔ یہ لوگ دولت مند تھے۔ زرگری کے ماہر تھے۔ تجارت پر چھائے ہوئے تھے۔ زراعت بھی خوب کرتے تھے۔ لیکن شکر و سپاس کی بجائے اللہ تعالیٰ کی شان میں گستاخیاں کرتے تھے۔ احکام ربانی میں تحریف کرتے تھے۔ سود کھاتے تھے، جھوٹ بولتے تھے، ہیرا پھیری میں طاق تھے۔ شرک کی گندگی میں مبتلا تھے۔\nماضی میں یہودیوں نے انبیائے کرام کی توہین کی اور بعض نبیوں کو قتل کر ڈالا۔ رسول اللہ صلی اللہ علیہ وسلم مدینہ منورہ تشریف لائے تو انھوں نے آپ صلی اللہ علیہ وسلم سے سخت معاندانہ رویہ اختیار کیا۔ آپ صلی اللہ علیہ وسلم نے انھیں اپنے لطف و کرم سے نوازا۔ انھیں مسلمانوں کے برابر حقوق مرحمت فرمائے۔ ان کی سماجی اور مذہبی آزادی کا تحفظ فرمایا۔ لیکن ان بدخصلت لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کے احسانات کا جواب بدعہدی، غداری اور سفاکی سے دیا۔ انھوں نے محسن انسانیت صلی اللہ علیہ وسلم کو متعدد بار شہید کرنے کی سازش کی۔ اگلے اوراق میں قرآن کریم کی آیات کی روشنی میں یہودیوں کے یہی خدوخال اجاگر کیے گئے ہیں۔","",{"v":500149}],[2220,"§یہود مدینہ کی سازشیں اور جسارتیں\nجب اللہ تعالیٰ نے اہل عرب کو یہ اعزاز بخشا کہ آخری نبی ان میں سے چنا اور انھیں محمد رسول اللہ صلی اللہ علیہ وسلم کے ذریعے عزت عطا فرمائی، ان کی آنکھوں سے جاہلیت کے پردے ہٹا دیے اور ان کو قوت اور غلبہ عطا فرمایا تو یہودی حسد اور بغض کی آگ میں جلنے لگے۔ وہ سمجھے بیٹھے تھے کہ آخری نبی یا ان کا مسیحا (Messiah) انھی میں سے مبعوث ہوگا مگر جب یہ اعزاز بنو اسماعیل کو مل گیا تو حسد کے مارے انھوں نے خاتم الانبیاء صلی اللہ علیہ وسلم کے بارے میں ہٹ دھرمی اور کفر و انکار کی روش اختیار کی۔ نبی صلی اللہ علیہ وسلم کی مدینہ آمد پر بنو نضیر کے سردار حیی بن اخطب اور اس کے بھائی ابو یاسر کی طرف سے شدید معاندانہ رویے کا اظہار ہوا۔ یہود نے اپنے حسد، بغض اور دشمنی کا اظہار ہر طریقے سے کیا۔ اللہ تعالیٰ کی ذات کو ناقص صفات سے متصف کیا، اللہ کے رسول صلی اللہ علیہ وسلم سے مشکل سوالات کیے اور تمسخر اڑایا، آپ کے قتل کی سازشیں کیں، جھوٹی افواہیں پھیلائیں، دشمنوں کی مدد کی، غرض انھوں نے ہر وہ طریقہ اختیار کیا جو وہ بزعم خویش اسلام کو مٹانے کے لیے کر سکتے تھے۔\n[تصویر: پر اسرار یہودی گروپ کی مخصوص علامت]\nاس کے باوجود انھوں نے حق کو غالب اور اپنے مکر و فریب اور سازشوں کو ناکام ہوتے دیکھا تو ان میں سے بعض نے اسلام کی عداوت کو دل میں رکھتے ہوئے ظاہراً اسلام قبول کیا تاکہ قتل اور رسوا ہونے سے بچ جائیں۔ ان کی دوستیاں اور ہمدردیاں یہود ہی کے ساتھ تھیں لیکن بظاہر وہ مسلمان تھے۔\n§قبائل یہود کے معروف دشمنان اسلام\nمدینہ منورہ کے یہودی اسلام دشمنی میں سب سے آگے تھے۔ ان کے ساتھ وہ لوگ بھی شامل تھے جو ہر چند بلحاظ عقیدہ یہودی ہی تھے لیکن ان کا تعلق یہودی قبائل سے نہ تھا۔ ان کے علاوہ ایسے افراد بھی دعوت اسلام","",{"v":500150,"im":["v5_p150.jpg"]}],[2221,"کی مزاحمت کر رہے تھے جو بعد ازاں خود مشرف بہ اسلام ہو گئے ان لوگوں کی فہرست درج ذیل ہے۔\nبنو نضیر: حیی بن اخطب، ابو یاسر بن اخطب، جدی بن اخطب، سلام بن مشکم، کنانہ بن الربیع بن ابی الحقیق، سلام بن ابی الحقیق جس کی کنیت ابو رافع الاعور تھی (اسے رسول اللہ صلی اللہ علیہ وسلم کے ساتھیوں نے خیبر کے موقع پر قتل کیا)۔ ربیع بن الربیع بن ابی الحقیق، عمرو بن جحاش، کعب بن اشرف (یہ قبیلہ طے کی شاخ بنی نبہان میں سے تھا اور اس کی ماں بنو نضیر سے تھی) اور اس کے دونوں حلیف حجاج بن عمرو اور کردم بن قیس۔\nبنو ثعلبہ بن الفطیون: عبداللہ بن صوریا الاعور (اس زمانے میں حجاز میں اس سے زیادہ تورات کا جاننے والا کوئی نہ تھا)، ابن صلوبا، مخیریق (یہ یہود کے بہت بڑے عالم تھے، انھوں نے اسلام قبول کر لیا تھا۔)\nبنو قینقاع: زید بن اللصیت، سعد بن حنیف، محمود بن سیحان، عزیر بن ابی عزیز، عبداللہ بن صیف، سوید بن حارث، رفاعہ بن قیس، فنحاص، اشیع، نعمان بن اضا، بحری بن عمرو، شاس بن عدی، شاس بن قیس، زید بن حارث، نعمان بن عمرو، سکین بن ابی سکین، عدی بن زید، ابو انس نعمان بن ابی اوفی، محمود بن دحیہ، مالک بن صیف، کعب بن راشد، عازر، رافع بن ابی رافع، خالد، ازار بن ابی ازار، رافع بن حارثہ، رافع بن حریملہ، رافع بن خارجہ، مالک بن عوف، رفاعہ بن زید بن التابوت، عبداللہ بن سلام بن حارث (یہ یہود کے سب سے بڑے عالم تھے۔ ہجرت نبوی کے بعد مسلمان ہو گئے۔ ان کا نام الحصین تھا، رسول اللہ صلی اللہ علیہ وسلم نے ان کا نام عبداللہ رکھا۔)\n[تصویر: وہران (الجزائر) کا قدیم یہودی معبد جو اب مسجد عبداللہ بن سلام ہے]","",{"v":500151,"im":["v5_p151.jpg"]}],[2222,"بنو قریظہ: زبیر بن باطا بن وہب، عزال بن شمویل، کعب بن اسد (اسی نے بنو قریظہ والا عہد کیا تھا جو غزوہ احزاب کے موقع پر توڑ دیا گیا)، شمویل بن زید، جبل بن عمرو بن سکینہ، نظام بن زید، قردم بن کعب، وہب بن زید، نافع بن ابی نافع، ابو نافع، عدی بن زید، حارث بن عوف، کردم بن زید، اسامہ بن حبیب، رافع بن رمیلہ، جبل بن ابی قشیر، وہب بن یہودا۔\nبنو زریق: ان میں سے لبید بن اعصم یہودی تھا جس نے رسول اللہ صلی اللہ علیہ وسلم پر جادو کیا تھا۔\nبنو حارثہ: کنانہ بن صوریا یہودی انھی میں سے تھا۔\nبنو عمرو: یہود بنو عمرو میں سے قردم بن عمرو تھا۔\nبنو نجار: ان میں سے سلسلہ بن برہام یہودی تھا۔\nیہ وہ یہودی تھے جو رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ سے دشمنی اور شر پھیلانے اور اسلام کے خلاف سازشیں کرنے میں آگے آگے تھے، ان لوگوں سے عبداللہ بن سلام اور مخیریق مستثنیٰ ہیں کیونکہ ان دونوں حضرات نے اسلام قبول کر لیا تھا۔(1)\n[تصویر: کرسمس کے دنوں ہی میں منائے جانے والے یہودی تہوار ’’ضیافت انوار‘‘ (مینورا) کی شمعیں]\nیہود مدینہ میں وہ تمام عیوب پائے جاتے تھے جن کے لیے وہ دنیا بھر میں شروع ہی سے بدنام چلے آتے ہیں یہ لوگ شرک کی گندگی میں ڈوبے ہوئے تھے۔ اللہ رب العزت کی شان میں بے ادبی کرتے تھے۔ احکام الٰہی میں تحریف کرتے تھے۔ سود کھاتے تھے۔ جھوٹ بولتے تھے۔ غداری اور معاہدہ شکنی میں ثانی نہ رکھتے تھے۔ ان کی کارگزاریوں کا ذکر قرآن حکیم کی کئی سورتوں میں کیا گیا ہے، ان کے فکر و عمل کی گمراہیوں کی تفصیل درج ذیل ہے:","",{"v":500152,"fn":"(1) السيرة لابن هشام: 514-516/2، البداية والنهاية: 235,236/3","im":["v5_p152.jpg"]}],[2223,"§شرک\nبرے اعمال میں سب سے زیادہ قبیح اور گھناؤنا عمل اللہ تعالیٰ کے ساتھ کسی کو شریک ٹھہرانا ہے۔ یہ عادت بد یہود میں بدرجہ اتم موجود تھی۔ وہ عزیر علیہ السلام کو اللہ کا بیٹا قرار دیتے تھے۔ ان کی اس روش کا تذکرہ قرآن میں اس طرح کیا گیا ہے، اللہ تعالیٰ کا فرمان ہے:\n﴿وَقَالَتِ الْيَهُودُ عُزَيْرٌ ابْنُ اللَّهِ وَقَالَتِ النَّصَارَى الْمَسِيحُ ابْنُ اللَّهِ ذَلِكَ قَوْلُهُمْ بِأَفْوَاهِهِمْ يُضَاهِئُونَ قَوْلَ الَّذِينَ كَفَرُوا مِنْ قَبْلُ قَاتَلَهُمُ اللَّهُ أَنَّى يُؤْفَكُونَ ۝ اتَّخَذُوا أَحْبَارَهُمْ وَرُهْبَانَهُمْ أَرْبَابًا مِنْ دُونِ اللَّهِ وَالْمَسِيحَ ابْنَ مَرْيَمَ وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا إِلَهًا وَاحِدًا لَا إِلَهَ إِلَّا هُوَ سُبْحَانَهُ عَمَّا يُشْرِكُونَ ۝﴾\n’’اور یہودیوں نے کہا: عزیر اللہ کا بیٹا ہے اور عیسائیوں نے کہا: عیسی اللہ کا بیٹا ہے۔ یہ ان کے منہ کی بات ہے۔ یہ اس سے پہلے کے کافروں کی بات کی ریس کرتے ہیں۔ اللہ انھیں ہلاک کرے، یہ کہاں بہکے پھرتے ہیں۔ انھوں نے اللہ کو چھوڑ کر اپنے علماء اور درویشوں کو (اپنا) رب بنا لیا اور مسیح ابن مریم کو (بھی) حالانکہ انھیں یہی حکم دیا گیا تھا کہ وہ صرف ایک معبود (اللہ) کی عبادت کریں جس کے سوا کوئی معبود نہیں۔ وہ اس شرک سے پاک ہے جو وہ کرتے ہیں۔‘‘(1)\nاندھیر در اندھیر کے مصداق یہودی محض مشرک ہی نہیں تھے بلکہ ان کے دماغ میں اپنی برتری اور فوقیت کا نشہ بھی بھرا ہوا تھا۔ اس تکبر اور رعونت کی وجہ سے وہ اپنے من گھڑت افکار و عقائد سے دستبردار ہونے کے لیے تیار نہیں تھے۔ وہ اپنے باطل افکار و اعمال کی وجہ سے محمد رسول اللہ صلی اللہ علیہ وسلم کی اتباع کو محال سمجھتے تھے۔\nابن اسحاق کہتے ہیں: سلام بن مشکم، ابو انس نعمان بن اوفی، محمود بن دحیہ، شاس بن قیس اور مالک بن صیف، رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے کہا: ہم آپ کی پیروی کس طرح کریں جبکہ آپ نے تو ہمارا قبلہ ہی چھوڑ دیا ہے اور آپ کا یہ دعویٰ بھی ہے کہ عزیر اللہ کے بیٹے نہیں۔ اللہ تعالیٰ نے ان کے بارے میں درج بالا آیت نازل فرمائی۔(2)\nیہودیوں کی گمراہی کا یہ عالم تھا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی دعوت توحید پر تعجب کا اظہار کرتے تھے۔ ابن اسحاق کی ایک دوسری روایت میں ہے کہ (یہود میں سے) نحام بن زید، قردم بن کعب اور بحری بن عمرو رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور کہا: اے محمد! واقعی کیا آپ اللہ کے سوا کسی اور الہ کو نہیں جانتے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ کے سوا","",{"v":500153,"fn":"(1) التوبة 9:30,31\n(2) السيرة لابن هشام: 570/2"}],[2224,"کوئی معبود برحق نہیں۔ مجھے اس کے ساتھ مبعوث کیا گیا ہے اور اسی کی طرف میں دعوت دیتا ہوں۔ اس وقت اللہ تعالیٰ نے یہ آیات نازل فرمائیں:\n﴿قُلْ أَيُّ شَيْءٍ أَكْبَرُ شَهَادَةً قُلِ اللَّهُ شَهِيدٌ بَيْنِي وَبَيْنَكُمْ وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنْذِرَكُمْ بِهِ وَمَنْ بَلَغَ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ اللَّهِ آلِهَةً أُخْرَى قُلْ لَا أَشْهَدُ قُلْ إِنَّمَا هُوَ إِلَهٌ وَاحِدٌ وَإِنَّنِي بَرِيءٌ مِمَّا تُشْرِكُونَ ۝ الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يَعْرِفُونَهُ كَمَا يَعْرِفُونَ أَبْنَاءَهُمُ الَّذِينَ خَسِرُوا أَنْفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ ۝﴾ (الأنعام 6:19,20)\n’’ (اے نبی! ان سے) کہیے گواہی کے طور پر کون سی چیز سب سے بڑھ کر ہے؟ فرما دیجیے: اللہ میرے اور تمھارے درمیان گواہ ہے اور میری طرف یہ قرآن وحی کیا گیا ہے تاکہ اس کے ذریعے سے میں تمھیں اور جس جس کو یہ پہنچے سب کو ڈراؤں۔ کیا تم اس کی گواہی دیتے ہو کہ اللہ کے ساتھ دوسرے معبود بھی ہیں؟ کہہ دیجیے: میں یہ گواہی نہیں دیتا۔ کہہ دیجیے صرف وہی ایک معبود ہے اور بے شک میں اس شرک سے بری ہوں جو تم کرتے ہو۔ جن لوگوں کو ہم نے کتاب دی، وہ اسے اس طرح پہچانتے ہیں جس طرح اپنے بیٹوں کو پہچانتے ہیں۔ جن لوگوں نے اپنے آپ کو خسارے میں ڈالا تو وہ ایمان نہیں لاتے۔‘‘(1)\n§ذات باری تعالیٰ کی شان میں بے ادبی\nیہودیوں کا ایک جتھا رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا۔ انھوں نے کہا: اے محمد! جب سب کچھ اللہ ہی نے پیدا کیا ہے تو آخر اللہ کو کس نے پیدا کیا ہے؟ یہ سن کر آپ صلی اللہ علیہ وسلم کو شدید غصہ آیا اور آپ صلی اللہ علیہ وسلم ان لوگوں پر اس قدر ناراض ہوئے کہ آپ صلی اللہ علیہ وسلم کے چہرہ مبارک کا رنگ بدل گیا۔ آپ صلی اللہ علیہ وسلم نے ان لوگوں کی سخت گرفت فرمائی۔ اسی دوران حضرت جبریل علیہ السلام تشریف لے آئے۔ انھوں نے آپ صلی اللہ علیہ وسلم کو تسلی دی اور درخواست کی کہ آپ خاطر جمع رکھیں۔ بعد ازاں انھوں نے متذکرہ گستاخ یہودی کے سوال کے جواب میں خود اللہ رب العزت کی طرف سے عطا کردہ یہ جواب مرحمت فرمایا:\n﴿قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ۝﴾ (الإخلاص 112:1-4)\n”آپ کہہ دیجیے: وہ اللہ ایک ہے۔ اللہ بے نیاز ہے۔ اس نے (کسی کو) نہیں جنا اور نہ وہ (خود) جنا گیا۔","",{"v":500154,"fn":"(1) السيرة لابن هشام: 568/2"}],[2225,"§اور کوئی اس کا ہمسر نہیں۔“\nجب آپ صلی اللہ علیہ وسلم نے یہ سورت ان یہود کے سامنے تلاوت فرمائی تو انھوں نے کہا: اے محمد! ہمیں تو اپنے رب کے خلقی اوصاف بتائیے؟ اس کا ہاتھ کیسا ہے؟ اس کا بازو کیسا ہے؟ یہ لغو سوالات سن کر رسول اللہ صلی اللہ علیہ وسلم پہلے سے بھی زیادہ غیظ و غضب میں آگئے اور ان کے اقوال کا رد کرنے لگے۔ جبریل علیہ السلام پھر آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ آپ صلی اللہ علیہ وسلم کو تسلی دی اور اللہ تعالیٰ کی طرف سے لایا ہوا یہ جواب بیان کر دیا:\n﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ ۝﴾ (الزمر 39:67)\n’’اور انھوں نے اللہ کی قدر نہیں جانی جیسا کہ اس کی قدر کرنے کا حق ہے اور قیامت کے دن ساری زمین اس کی مٹھی میں ہوگی اور آسمان اس کے دائیں ہاتھ میں لپٹے ہوں گے۔ وہ پاک ہے اور اس شرک سے بالکل بالاتر ہے جو وہ کرتے ہیں۔‘‘(1)\n§فنحاص یہودی کی اشتعال انگیز جسارت\nایک دفعہ ابوبکر رضی اللہ عنہ یہود کے معبد بیت المدراس میں گئے۔ وہاں انھوں نے بہت سے لوگوں کو فنحاص نامی ایک آدمی کے گرد جمع دیکھا۔ یہ شخص یہود کا ایک عالم تھا۔ اس کے ساتھ ایک اور عالم اشیع بھی موجود تھا۔ ابوبکر رضی اللہ عنہ نے فنحاص سے کہا: دیکھو! اللہ سے ڈرو اور مسلمان ہو جاؤ۔ اللہ کی قسم! تم جانتے ہو کہ محمد صلی اللہ علیہ وسلم اللہ کے سچے رسول ہیں۔ وہ اللہ کی طرف سے حق لے کر آئے ہیں یہی حقیقت تمھاری تورات اور انجیل میں بھی لکھی ہوئی ہے۔ فنحاص نے کہا: ابوبکر! اللہ کی قسم! ہمیں تو اللہ کی کوئی محتاجی نہیں بلکہ اللہ ہمارا محتاج ہے۔ جس طرح وہ ہمارے آگے گڑگڑاتا ہے، ہم نہیں گڑگڑاتے۔ ہم اس سے بے نیاز ہیں۔ وہ ہم سے بے نیاز نہیں اور اگر وہ بے نیاز ہوتا تو ہم سے ہمارے اموال قرض کیوں مانگتا، جیسا کہ تمھارے ساتھی کا دعویٰ ہے۔ وہ تمھیں سود سے منع کرتا ہے اور خود ہمیں سود دیتا ہے۔ اگر وہ ہم سے بے نیاز ہوتا تو ہمیں سود نہ دیتا۔ (معاذ اللہ) ابوبکر رضی اللہ عنہ کو یہودی کی یہ بات سن کر اتنا غصہ آیا کہ آپ نے اس کے چہرے پر بڑے زور سے طمانچہ رسید کیا اور کہا: اے اللہ کے دشمن! اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اگر ہمارے اور تمھارے مابین معاہدہ نہ ہوتا تو میں ابھی تیرا سر تن سے جدا کر دیتا۔ فنحاص رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا اور کہا: اے محمد! دیکھیے آپ کے ساتھی نے میرا کیا حشر کیا ہے؟","",{"v":500155,"fn":"(1) السيرة لابن هشام: 571,572/2"}],[2226,"رسول اللہ صلی اللہ علیہ وسلم نے ابوبکر رضی اللہ عنہ سے دریافت کیا: ’’تمھیں ایسا کرنے پر کس چیز نے اکسایا؟‘‘ ابوبکر رضی اللہ عنہ نے کہا: اے اللہ کے رسول! اس اللہ کے دشمن نے انتہائی سنگین بات کہی: اس نے کہا کہ اللہ محتاج ہے اور ہم بے نیاز ہیں۔ جب اس نے یہ کہا تو میں اللہ کی ذات عالی کے لیے غصے میں آگیا اور اسے تھپڑ دے مارا۔ فنحاص نے اس کا انکار کیا اور کہا: میں نے یہ بات نہیں کی۔ اللہ تعالیٰ نے فنحاص کے رد اور ابوبکر رضی اللہ عنہ کی تصدیق و تائید میں یہ آیت نازل فرمائی:\n﴿لَقَدْ سَمِعَ اللَّهُ قَوْلَ الَّذِينَ قَالُوا إِنَّ اللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَاءُ سَنَكْتُبُ مَا قَالُوا وَقَتْلَهُمُ الْأَنْبِيَاءَ بِغَيْرِ حَقٍّ وَنَقُولُ ذُوقُوا عَذَابَ الْحَرِيقِ ۝﴾ (آل عمران 3:181)\n’’بلاشبہ اللہ نے ان لوگوں کی بات سن لی جنھوں نے کہا: اللہ فقیر ہے اور ہم مال دار ہیں۔ یقیناً ان کی یہ بات ہم لکھ لیں گے اور (وہ بھی) جو وہ نبیوں کو ناحق قتل کرتے رہے اور (قیامت کے دن) ہم ان سے کہیں گے: اب جلانے والے عذاب کا مزہ چکھو۔‘‘\nاور جو بات ابوبکر صدیق رضی اللہ عنہ کے غصے کا سبب بنی، اس کے بارے میں یہ آیت نازل ہوئی:\n﴿لَتُبْلَوُنَّ فِي أَمْوَالِكُمْ وَأَنْفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ وَمِنَ الَّذِينَ أَشْرَكُوا أَذًى كَثِيرًا وَإِنْ تَصْبِرُوا وَتَتَّقُوا فَإِنَّ ذَلِكَ مِنْ عَزْمِ الْأُمُورِ ۝﴾ (آل عمران 3:186)\n’’البتہ تمھیں تمھارے مالوں اور تمھاری جانوں کے بارے میں ضرور آزمایا جائے گا اور تم ان لوگوں سے جنھیں تم سے پہلے کتاب دی گئی اور ان لوگوں سے جنھوں نے شرک کیا، ضرور تکلیف دینے والی باتیں سنو گے اور اگر تم صبر اور پرہیزگاری اختیار کرو تو بے شک یہ بڑی ہمت کا کام ہے۔‘‘(1)\n§یہود کا اللہ تعالیٰ سے بخل منسوب کرنا\nسیدنا ابن عباس رضی اللہ عنہما کہتے ہیں کہ نباش بن قیس ایک یہودی تھا۔ ایک دن اس نے بڑی دریدہ دہنی کی، کہنے لگا: (نعوذ باللہ) رب بخیل ہے، خرچ نہیں کرتا۔ تب اللہ تعالیٰ نے یہ آیت نازل فرمائی:\n﴿وَقَالَتِ الْيَهُودُ يَدُ اللَّهِ مَغْلُولَةٌ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا بِمَا قَالُوا بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنْفِقُ كَيْفَ يَشَاءُ وَلَيَزِيدَنَّ كَثِيرًا مِنْهُمْ مَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ طُغْيَانًا وَكُفْرًا وَأَلْقَيْنَا بَيْنَهُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ إِلَى يَوْمِ الْقِيَامَةِ كُلَّمَا أَوْقَدُوا نَارًا لِلْحَرْبِ أَطْفَأَهَا اللَّهُ وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا وَاللَّهُ لَا يُحِبُّ الْمُفْسِدِينَ ۝﴾ (المائدة 5:64)","",{"v":500156,"fn":"(1) السيرة لابن هشام: 558,559/2"}],[2227,"’’اور یہودیوں نے کہا: اللہ کا ہاتھ بندھا ہوا ہے۔ بندھ گئے انھی کے ہاتھ اور لعنت پڑی ان پر ان کے اس قول کی وجہ سے۔ بلکہ اللہ کے تو دونوں ہاتھ کھلے ہیں۔ وہ جیسے چاہے خرچ کرتا ہے۔ حقیقت یہ ہے کہ یہ (قرآن) جو آپ کے رب کی طرف سے آپ پر نازل کیا گیا ہے، ان میں سے اکثر لوگوں کی سرکشی اور کفر میں اضافے کا باعث بنے گا اور ہم نے قیامت کے دن تک ان کے درمیان دشمنی اور بغض ڈال دیا ہے۔ جب کبھی وہ لڑائی کی آگ بھڑکاتے ہیں تو اللہ اسے بجھا دیتا ہے اور وہ زمین میں فساد کرنے کو دوڑتے ہیں اور اللہ فساد کرنے والوں کو پسند نہیں کرتا۔‘‘(1)\nیہود کی خوفناک جسارت اس حد تک بڑھی ہوئی تھی کہ انھوں نے اللہ تعالیٰ کو محض انسان کے مشابہ ہی قرار نہیں دیا بلکہ انسان میں موجود ناقص صفات سے بھی اللہ تعالیٰ کو متصف کیا۔ ان میں سے کچھ صفات کا تذکرہ درج ذیل ہے:\n(نعوذ باللہ) اللہ تعالیٰ تھک جاتا ہے اور آرام فرماتا ہے\nچونکہ یہودیوں کی نگاہ میں اللہ تعالیٰ انسان کے مشابہ قرار پایا، لہذا اس کا کوئی کام کر کے تھک جانا اور پھر آرام کا طلب گار ہونا بھی ضروری ٹھہرا۔\nامام قتادہ رحمہ اللہ بیان کرتے ہیں: اللہ تعالیٰ یہودیوں پر لعنت کرے۔ یہودیوں کا کہنا تھا: اللہ تعالیٰ نے آسمان و زمین کو چھ دن میں پیدا کیا، پھر ساتویں دن، یعنی ہفتے کے دن آرام کیا اور اسے وہ يَوْمُ الرَّاحَةِ یعنی آرام کا دن کہتے تھے۔ اللہ تعالیٰ نے ان کی تردید کرتے ہوئے فرمایا:\n﴿وَمَا مَسَّنَا مِنْ لُغُوبٍ ۝﴾ (ق 50:38)\n’’اور ہمیں کسی قسم کی تھکاوٹ نے نہیں چھوا۔‘‘\nیعنی در ماندگی، تھکاوٹ اور کسی قسم کی کوئی تکلیف نہیں ہوئی جیسا کہ اللہ تعالیٰ نے ایک دوسری آیت میں فرمایا:\n﴿أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَلَمْ يَعْيَ بِخَلْقِهِنَّ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى ۝﴾ (الأحقاف 46:33)\n”کیا انھوں نے نہیں دیکھا کہ جس اللہ نے آسمانوں اور زمین کو پیدا کیا اور ان کے پیدا کرنے سے تھکا","",{"v":500157,"fn":"(1) الاستيعاب في بيان الأسباب: 71/2، یہ روایت ضعیف ہے۔"}]])